package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Spots along a shared edge: neighbouring tiles lined up along the same bank counter or riverbank,
 * all facing it.
 *
 * <p>Spots sit on a grid fixed to the map: every spacing along the edge, and rows behind it, each
 * row in the gaps of the one in front. The rules keep a busy edge calm:
 * <ul>
 * <li>Anyone who has a spot keeps it for as long as they stay, whoever else comes and goes.</li>
 * <li>A newcomer takes the free spot at the edge nearest their own tile, and only if the edge is
 * full, the nearest spot in a row behind their tile's stretch of it (its share of the line between
 * its neighbours, in proportion to how many people each has). Nobody is ever put past someone from
 * the next tile along, so tiles keep their people in order.</li>
 * <li>Someone who steps away has their spot kept for them for {@link SlotBook#HOLD_TICKS}.</li>
 * <li>At most one person a tick steps forward from a row behind into a free spot at the edge.</li>
 * <li>Edge spots only count where the edge is really in front (water or a counter), so a line never
 * runs on past the end of the water.</li>
 * </ul>
 *
 * <p>Client thread only. Knows nothing about RuneLite; unit tested.
 */
final class LineBook
{
	/** Rows that may stand behind the edge. */
	static final int ROWS_BEHIND = 3;
	/** Least distance between rows, so rods and axes from behind clear the people in front. */
	static final int ROW_GAP = 48;

	private static final int TILE = 128;
	/** Any edge spot in a tile's stretch is better than any spot in a row behind. */
	private static final double ROW_COST = 1_000_000;

	/** What the book needs to know about the ground. */
	interface Terrain
	{
		/** Whether a player on this tile could be drawn at (dx, dz) from its middle. */
		boolean canStand(long tile, int dx, int dz);

		/** Whether a player on this tile facing {@code angle} is up against the edge (water or a counter). */
		boolean facesEdge(long tile, double angle);
	}

	/** One tile on a shared line this tick. */
	static final class Member
	{
		final long tile;
		/** Position along the line, in tiles. */
		final int along;
		/** Players who may be given a spot, in the order they're given one. */
		final List<Integer> ids;
		/** Someone who stays put (you, or anyone past the per-tile limit) is standing in the middle. */
		final boolean middleTaken;
		/** Most people this tile shows. */
		final int capacity;

		Member(long tile, int along, List<Integer> ids, boolean middleTaken, int capacity)
		{
			this.tile = tile;
			this.along = along;
			this.ids = ids;
			this.middleTaken = middleTaken;
			this.capacity = capacity;
		}

		double centre()
		{
			return along * (double) TILE;
		}
	}

	/** Tiles next to each other along one edge, all facing it. */
	static final class Line
	{
		final int plane;
		final int sideX;
		final int sideY;
		final int across;
		final double angle;
		final int spacing;
		/** In order along the line. */
		final List<Member> members;
		/** How far along the line spots may go, in local units: halfway to anyone else's row. */
		final double from;
		final double to;
		/** Whether this line may curve round each tile's booth: only where nobody stands behind it. */
		final boolean bow;

		Line(int plane, int sideX, int sideY, int across, double angle, int spacing, List<Member> members, double from, double to)
		{
			this(plane, sideX, sideY, across, angle, spacing, members, from, to, false);
		}

		Line(int plane, int sideX, int sideY, int across, double angle, int spacing, List<Member> members, double from, double to,
			boolean bow)
		{
			this.bow = bow;
			this.plane = plane;
			this.sideX = sideX;
			this.sideY = sideY;
			this.across = across;
			this.angle = angle;
			this.spacing = spacing;
			this.members = members;
			this.from = from;
			this.to = to;
		}

		String key()
		{
			return plane + ":" + sideX + ":" + sideY + ":" + across + ":" + spacing;
		}

		long tileAt(int alongTiles)
		{
			return sideX != 0
				? StackRegistry.key(plane, alongTiles * sideX, across)
				: StackRegistry.key(plane, across, alongTiles * sideY);
		}

		int aheadX()
		{
			return (int) Math.round(-Math.sin(angle));
		}

		int aheadZ()
		{
			return (int) Math.round(-Math.cos(angle));
		}

		int rowGap()
		{
			return Math.max(spacing, ROW_GAP);
		}

		/** Where spot (row, j) is along the line. */
		double along(int row, long j)
		{
			return j * (double) spacing + (row % 2 == 1 ? spacing / 2.0 : 0);
		}
	}

	/** A spot someone has: which line, which row, which step along it, and the tile it was given on. */
	private static final class Spot
	{
		final String line;
		final int row;
		final long j;
		final long tile;

		Spot(String line, int row, long j, long tile)
		{
			this.line = line;
			this.row = row;
			this.j = j;
			this.tile = tile;
		}

		String point()
		{
			return line + "/" + row + "/" + j;
		}
	}

	/** What happened on a line this tick, for the troubleshooting report. */
	static final class LineReport
	{
		final int placed;
		final int blocked;

		LineReport(int placed, int blocked)
		{
			this.placed = placed;
			this.blocked = blocked;
		}
	}

	private final Map<Integer, Spot> spotOf = new HashMap<>();
	private final Map<Integer, Spot> held = new HashMap<>();
	private final Map<Integer, Integer> heldUntil = new HashMap<>();

	/** Diagnostics: people who stepped forward into a free spot at the edge; total. */
	long moves;

	private int tick;

	/**
	 * Your own player's id when your character may be moved, else -1. If you end up in a row behind
	 * while someone from your tile stands at the edge, you swap with them, once: what you're doing
	 * (fishing, banking) should look right on your own screen.
	 */
	int localId = -1;

	/** Whether each tile's people curve gently round their own booth, rather than standing dead flat. */
	boolean bow = true;

	private long localTile = Long.MIN_VALUE;
	private int localSince;
	private boolean sawLocal;

	/**
	 * Work out this tick's spots on every shared line.
	 *
	 * @param reports filled with what happened on each tile's line, by tile
	 * @return a placement for everyone given a spot; anyone left out has no spot
	 */
	List<StackSpreader.Placement> update(List<Line> lines, int tick, Terrain terrain, Map<Long, LineReport> reports)
	{
		sawLocal = false;
		this.tick = tick;
		// Who is where this tick.
		Map<Integer, Member> memberOf = new HashMap<>();
		Map<Integer, Line> lineOf = new HashMap<>();
		for (Line line : lines)
		{
			for (Member m : line.members)
			{
				for (int id : m.ids)
				{
					memberOf.put(id, m);
					lineOf.put(id, line);
				}
			}
		}

		// People who left, or moved to another tile or line.
		for (Iterator<Map.Entry<Integer, Spot>> it = spotOf.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Integer, Spot> e = it.next();
			Member m = memberOf.get(e.getKey());
			Line line = lineOf.get(e.getKey());
			if (m == null)
			{
				held.put(e.getKey(), e.getValue());
				heldUntil.put(e.getKey(), tick + SlotBook.HOLD_TICKS);
				it.remove();
			}
			else if (m.tile != e.getValue().tile || !line.key().equals(e.getValue().line))
			{
				it.remove();
			}
		}
		// Holds that ran out; people coming back to a spot held for them.
		for (Iterator<Map.Entry<Integer, Integer>> it = heldUntil.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<Integer, Integer> e = it.next();
			Member m = memberOf.get(e.getKey());
			Spot spot = held.get(e.getKey());
			if (m != null && m.tile == spot.tile && lineOf.get(e.getKey()).key().equals(spot.line))
			{
				spotOf.put(e.getKey(), spot);
			}
			if (m != null || e.getValue() < tick)
			{
				held.remove(e.getKey());
				it.remove();
			}
		}

		List<StackSpreader.Placement> out = new ArrayList<>();
		for (Line line : lines)
		{
			layOut(line, terrain, reports, out);
		}
		if (!sawLocal)
		{
			localTile = Long.MIN_VALUE;
		}
		return out;
	}

	private void layOut(Line line, Terrain terrain, Map<Long, LineReport> reports, List<StackSpreader.Placement> out)
	{
		String key = line.key();
		int s = line.spacing;
		List<Member> members = line.members;

		// Every spot the line may use, and whether a player could stand there.
		long firstJ = (long) Math.floor(line.from / s) - 1;
		long lastJ = (long) Math.ceil(line.to / s) + 1;
		Map<String, Boolean> usable = new HashMap<>();
		int blocked = 0;
		for (int row = 0; row <= ROWS_BEHIND; row++)
		{
			for (long j = firstJ; j <= lastJ; j++)
			{
				double p = line.along(row, j);
				if (p < line.from || p > line.to)
				{
					continue;
				}
				boolean ok = standable(line, row, p, terrain);
				usable.put(row + "/" + j, ok);
				blocked += ok ? 0 : 1;
			}
		}

		// Spots in use: people keeping theirs, and spots held for people who stepped away.
		Set<String> taken = new HashSet<>();
		for (Spot spot : held.values())
		{
			if (spot.line.equals(key))
			{
				taken.add(spot.point());
			}
		}
		Map<Member, List<Integer>> newcomers = new HashMap<>();
		for (Member m : members)
		{
			List<Integer> waiting = new ArrayList<>();
			int kept = 0;
			for (int id : m.ids)
			{
				Spot spot = spotOf.get(id);
				if (spot != null && kept < m.capacity && Boolean.TRUE.equals(usable.get(spot.row + "/" + spot.j))
					&& !blockedByMiddle(line, spot.row, line.along(spot.row, spot.j)) && taken.add(spot.point()))
				{
					kept++;
					continue;
				}
				spotOf.remove(id);
				waiting.add(id);
			}
			// You take your pick of what's free before the others on your tile, so arriving at an
			// edge settles in one step instead of settling and then swapping forward.
			if (waiting.remove((Integer) localId))
			{
				waiting.add(0, localId);
			}
			newcomers.put(m, waiting);
		}

		// Each tile's stretch of the line, shared in proportion to how many people each has.
		double[] lo = new double[members.size()];
		double[] hi = new double[members.size()];
		for (int i = 0; i < members.size(); i++)
		{
			lo[i] = i == 0 ? line.from : hi[i - 1];
			if (i == members.size() - 1)
			{
				hi[i] = line.to;
			}
			else
			{
				int here = Math.max(1, members.get(i).ids.size());
				int next = Math.max(1, members.get(i + 1).ids.size());
				hi[i] = members.get(i).centre() + TILE * (double) here / (here + next);
			}
		}

		// Where each tile's people would ideally stand: the whole line side by side, centred where the
		// people are, each tile's share in order. Newcomers aim for their tile's share, so a busy tile
		// between two quieter ones still gets room at the edge.
		double[] target = new double[members.size()];
		int total = 0;
		double weighted = 0;
		for (Member m : members)
		{
			int n = Math.min(m.capacity, m.ids.size());
			total += n;
			weighted += n * m.centre();
		}
		double lineCentre = total == 0 ? 0 : weighted / total;
		int before = 0;
		for (int i = 0; i < members.size(); i++)
		{
			int n = Math.min(members.get(i).capacity, members.get(i).ids.size());
			double t = lineCentre + (before + n / 2.0 - total / 2.0) * s;
			target[i] = Math.max(line.from, Math.min(line.to, t));
			before += n;
		}

		// Newcomers, taking turns one tile at a time, so every tile claims its share of the edge
		// before any tile spreads out along someone else's.
		int[] next = new int[members.size()];
		int[] assigned = new int[members.size()];
		for (int i = 0; i < members.size(); i++)
		{
			assigned[i] = members.get(i).ids.size() - newcomers.get(members.get(i)).size();
		}
		boolean progress = true;
		while (progress)
		{
			progress = false;
			for (int i = 0; i < members.size(); i++)
			{
				Member m = members.get(i);
				List<Integer> waiting = newcomers.get(m);
				if (next[i] >= waiting.size() || assigned[i] >= m.capacity)
				{
					continue;
				}
				int id = waiting.get(next[i]++);
				String best = bestFree(line, i, id, target[i], lo[i], hi[i], usable, taken, 0);
				if (best == null)
				{
					// Nothing left for this tile; nobody else from it will fit either.
					next[i] = waiting.size();
					continue;
				}
				String[] parts = best.split("/");
				Spot spot = new Spot(key, Integer.parseInt(parts[0]), Long.parseLong(parts[1]), m.tile);
				spotOf.put(id, spot);
				taken.add(spot.point());
				assigned[i]++;
				progress = true;
			}
		}

		// Once you've stood here a moment, you get a place at the edge if anyone from your tile has
		// one: swap with whoever of them stands nearest your tile's middle. Not while an edge spot is
		// being held for someone from your tile: when that hold ends you step forward into it instead,
		// and nobody else has to move.
		Spot mine = spotOf.get(localId);
		if (mine != null && mine.line.equals(key))
		{
			sawLocal = true;
			if (localTile != mine.tile)
			{
				localTile = mine.tile;
				localSince = tick;
			}
		}
		boolean edgeHeld = false;
		for (Spot spot : held.values())
		{
			edgeHeld |= mine != null && spot.line.equals(key) && spot.row == 0 && spot.tile == mine.tile;
		}
		if (mine != null && mine.line.equals(key) && mine.row > 0 && !edgeHeld && tick - localSince >= SlotBook.LOCAL_SWAP_DELAY)
		{
			for (Member m : members)
			{
				if (!m.ids.contains(localId))
				{
					continue;
				}
				int swapWith = -1;
				double nearest = Double.MAX_VALUE;
				for (int id : m.ids)
				{
					Spot theirs = spotOf.get(id);
					if (id == localId || theirs == null || theirs.row != 0)
					{
						continue;
					}
					double distance = Math.abs(line.along(0, theirs.j) - m.centre());
					if (distance < nearest)
					{
						nearest = distance;
						swapWith = id;
					}
				}
				if (swapWith >= 0)
				{
					Spot theirs = spotOf.get(swapWith);
					spotOf.put(localId, new Spot(key, 0, theirs.j, m.tile));
					spotOf.put(swapWith, new Spot(key, mine.row, mine.j, m.tile));
					moves++;
				}
			}
		}

		// One person a tick steps forward into a free spot at the edge in their own stretch.
		stepForward:
		for (int pass = 0; pass < 2; pass++)
		{
			for (int i = 0; i < members.size(); i++)
			{
				for (int id : members.get(i).ids)
				{
					// You first, then everyone else in order along the line.
					if ((pass == 0) != (id == localId))
					{
						continue;
					}
					Spot spot = spotOf.get(id);
					if (spot == null || spot.row == 0)
					{
						continue;
					}
					taken.remove(spot.point());
					String best = bestFree(line, i, id, target[i], lo[i], hi[i], usable, taken, 0);
					if (best != null && best.startsWith("0/"))
					{
						Spot moved = new Spot(key, 0, Long.parseLong(best.split("/")[1]), spot.tile);
						spotOf.put(id, moved);
						taken.add(moved.point());
						moves++;
						break stepForward;
					}
					taken.add(spot.point());
				}
			}
		}

		// Anyone left without a spot is drawn in the middle of their tile, and so is whoever stays put
		// there: nobody at the edge is drawn on top of them. They keep their spot, so nothing
		// reshuffles; they just aren't shown while it's taken.
		Set<Integer> hidden = new HashSet<>();
		for (boolean changed = true; changed; )
		{
			changed = false;
			for (Member m : members)
			{
				boolean inMiddle = m.middleTaken;
				for (int id : m.ids)
				{
					inMiddle |= !spotOf.containsKey(id) || hidden.contains(id);
				}
				if (!inMiddle)
				{
					continue;
				}
				for (Member o : members)
				{
					for (int id : o.ids)
					{
						Spot spot = spotOf.get(id);
						if (spot != null && spot.row == 0 && Math.abs(line.along(0, spot.j) - m.centre()) < s && hidden.add(id))
						{
							changed = true;
						}
					}
				}
			}
		}

		// Placements.
		int placed = 0;
		int aheadX = line.aheadX();
		int aheadZ = line.aheadZ();
		for (Member m : members)
		{
			for (int id : m.ids)
			{
				Spot spot = spotOf.get(id);
				if (spot == null || hidden.contains(id))
				{
					continue;
				}
				double d = line.along(spot.row, spot.j) - m.centre();
				// Each tile's people curve round their own booth while their places along the line stay
				// exactly where they were: the line is still shared, it just isn't a flat wall of
				// people. Rows behind get back the depth the bow can cost them, since they stand half a
				// spacing along from the row in front, where the bow has moved away from them.
				int depth = spot.row * line.rowGap();
				if (bow && line.bow)
				{
					// A gentle curve round each booth along the line: whoever stands opposite one is at
					// the counter, and the people to either side of them fall back a little. It is
					// measured from the booth a spot sits at, not from the person's own tile and not
					// from the middle of the line, so it doesn't jump where two tiles meet and doesn't
					// change when a tile further along empties.
					double alongHere = line.along(spot.row, spot.j);
					double booth = Math.round((alongHere - m.centre()) / (double) TILE) * TILE + m.centre();
					depth += StackSpreader.bowBack(alongHere - booth);
				}
				out.add(new StackSpreader.Placement(id, m.tile,
					(int) Math.round(line.sideX * d - aheadX * depth), (int) Math.round(line.sideY * d - aheadZ * depth)));
				placed++;
			}
		}
		LineReport report = new LineReport(placed, blocked);
		for (Member m : members)
		{
			reports.put(m.tile, report);
		}
	}

	/**
	 * The free spot nearest {@code aim} for member {@code index}: anywhere along the edge first, then in a
	 * row behind its own stretch [lo, hi). Within a row, never past anyone from a tile further along
	 * or before anyone from a tile earlier on.
	 */
	private String bestFree(Line line, int index, int self, double aim, double lo, double hi, Map<String, Boolean> usable,
		Set<String> taken, int firstRow)
	{
		int s = line.spacing;
		String best = null;
		double bestCost = Double.MAX_VALUE;
		for (int row = firstRow; row <= ROWS_BEHIND; row++)
		{
			// Keep tiles in order along this row: nobody past someone from a tile further along.
			double before = -Double.MAX_VALUE;
			double after = Double.MAX_VALUE;
			for (int i = 0; i < line.members.size(); i++)
			{
				if (i == index)
				{
					continue;
				}
				// Someone staying put in the middle of a tile counts as that tile's person at the edge.
				if (row == 0 && line.members.get(i).middleTaken)
				{
					if (i < index)
					{
						before = Math.max(before, line.members.get(i).centre());
					}
					else
					{
						after = Math.min(after, line.members.get(i).centre());
					}
				}
				for (int id : line.members.get(i).ids)
				{
					Spot spot = spotOf.get(id);
					if (spot == null || id == self || spot.row != row)
					{
						continue;
					}
					double p = line.along(spot.row, spot.j);
					if (i < index)
					{
						before = Math.max(before, p);
					}
					else
					{
						after = Math.min(after, p);
					}
				}
			}
			double rowFrom = row == 0 ? line.from : lo;
			double rowTo = row == 0 ? line.to + 1 : hi;
			for (long j = (long) Math.floor(rowFrom / s) - 1; j <= (long) Math.ceil(rowTo / s) + 1; j++)
			{
				double p = line.along(row, j);
				String point = row + "/" + j;
				if (p < rowFrom || p >= rowTo || p <= before || p >= after
					|| !Boolean.TRUE.equals(usable.get(point)) || taken.contains(line.key() + "/" + point)
					|| blockedByMiddle(line, row, p))
				{
					continue;
				}
				double cost = row * ROW_COST + Math.abs(p - aim);
				if (cost < bestCost)
				{
					bestCost = cost;
					best = point;
				}
			}
		}
		return best;
	}

	/** Whether a spot at the edge is too close to someone staying put in the middle of their tile. */
	private static boolean blockedByMiddle(Line line, int row, double p)
	{
		if (row != 0)
		{
			return false;
		}
		for (Member m : line.members)
		{
			if (m.middleTaken && Math.abs(p - m.centre()) < line.spacing)
			{
				return true;
			}
		}
		return false;
	}

	/** Whether a player could be drawn at spot {@code p} in {@code row}, checked from the nearest tile on the line. */
	private static boolean standable(Line line, int row, double p, Terrain terrain)
	{
		Member owner = line.members.get(0);
		for (Member m : line.members)
		{
			if (Math.abs(p - m.centre()) < Math.abs(p - owner.centre()))
			{
				owner = m;
			}
		}
		double d = p - owner.centre();
		int depth = row * line.rowGap();
		if (!terrain.canStand(owner.tile, (int) Math.round(line.sideX * d - line.aheadX() * depth),
			(int) Math.round(line.sideY * d - line.aheadZ() * depth)))
		{
			return false;
		}
		// An edge spot needs the edge in front of it: past the end of the water, nobody lines up.
		return row != 0 || terrain.facesEdge(line.tileAt((int) Math.round(p / TILE)), line.angle);
	}

	void clear()
	{
		localTile = Long.MIN_VALUE;
		spotOf.clear();
		held.clear();
		heldUntil.clear();
	}
}

package com.grant9008.personalspace;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Settings. Everything here can also be changed from the Personal Space sidebar panel, which
 * writes through the same config keys, so the two always agree.
 */
@ConfigGroup(PersonalSpaceConfig.GROUP)
public interface PersonalSpaceConfig extends Config
{
	String GROUP = "personalspace";

	String KEY_ACTIVE = "active";
	String KEY_ARRANGEMENT = "arrangement";
	String KEY_MODE = "mode";
	String KEY_SPACING = "spacingUnits";
	String KEY_MAX_STACK = "maxStack";
	String KEY_INCLUDE_LOCAL = "includeLocalPlayer";
	String KEY_SMALL_GROUPS_CLOSE = "smallGroupsClose";
	String KEY_POSE = "smallGroupPose";
	String KEY_PAUSE_IN_COMBAT = "pauseInCombat";
	String KEY_TEST_OFFSET = "testOffset";

	int MIN_STACK = 2;
	int MAX_STACK = 16;
	int DEFAULT_STACK = 5;
	int MIN_TEST_OFFSET = 0;
	int MAX_TEST_OFFSET = 64;

	/** Spacing between players, in local units (128 is one tile). */
	int MIN_SPACING = 16;
	int MAX_SPACING = 256;
	int SPACING_CLOSE = 40;
	int SPACING_NORMAL = 128;
	/** Two tiles apart: what looks best in a big Grand Exchange crowd, so it's the default. Banks, fires and anvils stay closer on their own. */
	int SPACING_WIDE = 256;
	/**
	 * The slider sets the spacing for a full crowd. Two players on a tile stand at most this far apart
	 * (a bit over half a tile), and bigger groups spread further, reaching the slider's spacing at
	 * {@link #FULL_CROWD} players: two people two tiles apart just look lost.
	 */
	int PAIR_SPACING = 72;
	int FULL_CROWD = 8;
	/** Smart keeps people at a bank counter or row of booths at most this far apart, whatever the slider says. */
	int COUNTER_SPACING = 42;
	/** Smart keeps people around a fire at most this far apart, whatever the slider says. */
	int FIRE_SPACING = 46;

	enum Mode
	{
		SPREAD("Spread stacked players"),
		TEST_SHIFT_ME("Test: shift my character");

		private final String label;

		Mode(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** How two or three players standing together in the open are turned. */
	enum Pose
	{
		NATURAL("Natural"),
		ANGLED("Angled"),
		FACING("Facing");

		private final String label;

		Pose(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	enum Arrangement
	{
		AUTO("Smart"),
		CIRCLE("Circle"),
		ROW("Line"),
		ARC("Arc");

		private final String label;

		Arrangement(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Troubleshooting",
		description = "Test mode and settings for checking that Personal Space works.",
		position = 10,
		closedByDefault = true
	)
	String TROUBLESHOOTING = "troubleshooting";

	@ConfigItem(
		keyName = KEY_ACTIVE,
		name = "Spread out crowds",
		description = "Untick to pause without turning the plugin off. Everyone goes back to where they really stand.",
		position = 0
	)
	default boolean active()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_ARRANGEMENT,
		name = "Arrangement",
		description = "How everyone on a tile is drawn up. Smart: they line up along whatever they are facing, such as a bank counter, a wall or a fire, and stand in a ring out in the open where there is nothing to line up along. Circle: always a ring. Line: always side by side, even in the open, for a group photo. Arc: a curve, like the crowd round an anvil. Smart always keeps people out of booths, stalls, anvils and walls; the other three keep out of them too, but choose the shape themselves.",
		position = 1
	)
	default Arrangement arrangement()
	{
		return Arrangement.AUTO;
	}

	@Range(min = MIN_SPACING, max = MAX_SPACING)
	@ConfigItem(
		keyName = KEY_SPACING,
		name = "Spacing",
		description = "How far apart players are drawn, in game units (128 is one tile). With 'Auto-space' on this is a maximum: groups of 2 or 3, and anyone at a bank counter, a wall or a fire, stand closer. Turn 'Auto-space' off and this setting is used everywhere.",
		position = 2
	)
	default int spacing()
	{
		return SPACING_WIDE;
	}

	@Range(min = MIN_STACK, max = MAX_STACK)
	@ConfigItem(
		keyName = KEY_MAX_STACK,
		name = "Players per tile",
		description = "Spread out at most this many players on one tile (5 is the sweet spot). Anyone past that stays hidden in the middle, as in the normal game. A busy bank booth can have a dozen people on one tile, so raise it if you keep seeing a heap in the middle; the higher it goes, the further out the crowd reaches to make room.",
		position = 3
	)
	default int maxStack()
	{
		return DEFAULT_STACK;
	}

	@ConfigItem(
		keyName = KEY_INCLUDE_LOCAL,
		name = "Move my character too",
		description = "Off: your own character always stays exactly where it really is and other players step around you. On: you take a spot too, at the front, so what you're doing looks right.",
		position = 4
	)
	default boolean includeLocalPlayer()
	{
		return false;
	}

	@ConfigItem(
		keyName = KEY_PAUSE_IN_COMBAT,
		name = "Pause while I'm fighting",
		description = "On: everyone is shown where they really stand while you fight, and for a few seconds after. Keep this on for raids and group bosses, where standing on the same tile matters. Turn it off to keep seeing the crowd during ordinary fights like training or slayer.",
		position = 7
	)
	default boolean pauseInCombat()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_SMALL_GROUPS_CLOSE,
		name = "Auto-space",
		description = "On: the plugin picks sensible distances whatever the Spacing slider says, so groups of 2 or 3 stay close together and people at a bank counter, a wall or a fire stand shoulder to shoulder. Turn off to unlock the slider: it then sets exactly how far apart everyone stands, anywhere, handy for photos.",
		position = 5
	)
	default boolean smallGroupsClose()
	{
		return true;
	}

	@ConfigItem(
		keyName = KEY_POSE,
		name = "Small group pose",
		description = "How two or three players standing together in the open are turned. Natural: the way they really face. Angled: turned halfway towards each other, like a photo. Facing: towards each other. Players at an anvil, booth or fire keep facing it.",
		position = 6
	)
	default Pose pose()
	{
		return Pose.NATURAL;
	}

	@ConfigItem(
		keyName = KEY_MODE,
		name = "Mode",
		description = "Normal use is 'Spread stacked players'. The test mode ignores everyone else and just draws your own character a fixed distance east of where it really is, so you can check the basic effect on your own.",
		position = 11,
		section = TROUBLESHOOTING
	)
	default Mode mode()
	{
		return Mode.SPREAD;
	}

	@Range(min = MIN_TEST_OFFSET, max = MAX_TEST_OFFSET)
	@ConfigItem(
		keyName = KEY_TEST_OFFSET,
		name = "Test offset (units)",
		description = "Only used by the test mode. Draws your own character this many local units east of its real spot. 128 units is one tile, so 32 is a quarter tile.",
		position = 12,
		section = TROUBLESHOOTING
	)
	default int testOffset()
	{
		return 32;
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;

/**
 * Turns a {@link Snapshot} into plain-English status for the sidebar: one headline saying whether
 * the plugin is working and, if not, what to do; a list of individual checks; and a text report
 * that can be copied and pasted when asking for help. Pure logic, unit tested.
 */
final class StatusSummary
{
	enum Level
	{
		OK,
		WAITING,
		PAUSED,
		PROBLEM
	}

	static final class Headline
	{
		final Level level;
		final String title;
		final String detail;

		Headline(Level level, String title, String detail)
		{
			this.level = level;
			this.title = title;
			this.detail = detail;
		}
	}

	static final class Check
	{
		final Level level;
		final String label;
		final String value;

		Check(Level level, String label, String value)
		{
			this.level = level;
			this.label = label;
			this.value = value;
		}
	}

	private StatusSummary()
	{
	}

	static Headline headline(Snapshot s)
	{
		if (!s.active)
		{
			return new Headline(Level.PAUSED, "Off",
				"Flip the switch above to spread out crowds again.");
		}
		if (s.gate == Snapshot.Gate.NOT_LOGGED_IN)
		{
			return new Headline(Level.WAITING, "Waiting for you to log in", "Crowds are spread out once you're in game.");
		}
		if (s.gate != Snapshot.Gate.SAFE)
		{
			return new Headline(Level.PAUSED, "Paused for safety",
				s.gate.label + ". Everyone is shown where they really stand until then.");
		}
		if (s.renderer == null)
		{
			return new Headline(Level.PROBLEM, "Needs the GPU plugin",
				"Turn on the GPU plugin (or 117 HD) in RuneLite's plugin list.");
		}
		if (!s.hooked)
		{
			return new Headline(Level.PROBLEM, "Couldn't connect",
				"Turn Personal Space off and on again in the plugin list.");
		}
		if (s.noPlayerDrawsSustained)
		{
			return new Headline(Level.PROBLEM, "Something's not right",
				"Players aren't coming through. Open Troubleshooting below and press Copy report.");
		}

		if (s.mode == PersonalSpaceConfig.Mode.TEST_SHIFT_ME)
		{
			if (s.nudgedDrawsPerSec > 0)
			{
				return new Headline(Level.OK, "Test mode is on",
					"Your character is drawn " + s.testOffset + " units to the east. Turn test mode off in Troubleshooting when you're done.");
			}
			if (s.testOffset == 0)
			{
				return new Headline(Level.WAITING, "Test mode is on",
					"The test distance is 0. Drag the slider in Troubleshooting to see your character move.");
			}
			if (s.nothingMovedSustained)
			{
				return new Headline(Level.PROBLEM, "Test mode isn't moving you",
					"Open Troubleshooting below and press Copy report.");
			}
			return new Headline(Level.WAITING, "Test mode is on", "Moving your character now.");
		}

		if (s.stackedTiles == 0)
		{
			return new Headline(Level.WAITING, "No crowds here",
				"When players stand on the same tile, they'll be spread out automatically.");
		}
		if (s.nudgedDrawsPerSec + s.revealedDrawsPerSec > 0)
		{
			return new Headline(Level.OK, "Spreading " + plural(s.moving, "player") + " on " + plural(s.stackedTiles, "tile"),
				"Crowded tiles are opened up so you can see everyone.");
		}
		if (s.nothingMovedSustained)
		{
			return new Headline(Level.PROBLEM, "Something's not right",
				"Crowds were found but nobody was spread out. Open Troubleshooting below and press Copy report.");
		}
		return new Headline(Level.WAITING, "Found " + plural(s.stackedTiles, "crowded tile"), "Spreading them out now.");
	}

	static List<Check> checks(Snapshot s)
	{
		List<Check> out = new ArrayList<>();
		out.add(new Check(s.active ? Level.OK : Level.PAUSED, "Effect", s.active ? "On" : "Paused"));
		boolean loggedIn = s.gate != Snapshot.Gate.NOT_LOGGED_IN;
		out.add(new Check(loggedIn ? Level.OK : Level.WAITING, "Logged in", loggedIn ? "Yes" : "No"));
		if (loggedIn)
		{
			out.add(new Check(s.gate == Snapshot.Gate.SAFE ? Level.OK : Level.PAUSED, "Safety", s.gate.label));
		}
		out.add(new Check(s.renderer != null ? Level.OK : Level.PROBLEM, "Renderer", s.renderer != null ? s.renderer : "None (turn on GPU)"));
		// Not being connected is only a problem once you're in the world: we deliberately stay out of
		// the renderer's way at the login screen, while it is still starting up.
		out.add(new Check(s.hooked ? Level.OK : (loggedIn && s.renderer != null ? Level.PROBLEM : Level.WAITING),
			"Connected", s.hooked ? "Yes" : "No"));
		if (loggedIn && s.hooked)
		{
			out.add(new Check(s.playerDrawsPerSec > 0 ? Level.OK : (s.noPlayerDrawsSustained ? Level.PROBLEM : Level.WAITING),
				"Players drawn", s.playerDrawsPerSec + " / sec"));
		}
		out.add(new Check(Level.WAITING, "Players nearby", Integer.toString(s.nearby)));
		out.add(new Check(Level.WAITING, "Standing still", Integer.toString(s.still)));
		out.add(new Check(s.stackedTiles > 0 ? Level.OK : Level.WAITING, "Stacked tiles", Integer.toString(s.stackedTiles)));
		out.add(new Check(s.moving > 0 ? Level.OK : Level.WAITING, "Being spread", Integer.toString(s.moving)));
		boolean anyDrawn = s.nudgedDrawsPerSec + s.revealedDrawsPerSec > 0;
		Level drawnLevel = anyDrawn ? Level.OK : (s.nothingMovedSustained ? Level.PROBLEM : Level.WAITING);
		out.add(new Check(drawnLevel, "Drawn moved", s.nudgedDrawsPerSec + " / sec"));
		if (s.mode == PersonalSpaceConfig.Mode.SPREAD)
		{
			out.add(new Check(drawnLevel, "Hidden shown", s.revealedDrawsPerSec + " / sec"));
		}
		if (s.playersInOtherCalls > 0 || s.offThreadDraws > 0 || s.revealErrors > 0 || s.skippedIds > 0)
		{
			out.add(new Check(Level.PROBLEM, "Oddities", "see report"));
		}
		return out;
	}

	static String report(Snapshot s)
	{
		Headline h = headline(s);
		StringBuilder b = new StringBuilder();
		b.append("Personal Space ").append(s.pluginVersion).append(" report\n");
		b.append("Status: ").append(h.level).append(" - ").append(h.title).append('\n');
		b.append("Settings: effect ").append(s.active ? "on" : "paused")
			.append(", mode ").append(s.mode)
			.append(", arrangement ").append(s.arrangement)
			.append(", spacing ").append(s.spacing)
			.append(", max per tile ").append(s.maxStack)
			.append(", move me ").append(yesNo(s.includeLocal))
			.append(", small groups close ").append(yesNo(s.smallGroupsClose))
			.append(", pose ").append(s.pose)
			.append(", pause in combat ").append(yesNo(s.pauseInCombat))

			.append(", test offset ").append(s.testOffset).append('\n');
		b.append("Safety: ").append(s.gate.label).append('\n');
		b.append("Renderer: ").append(s.renderer == null ? "none" : s.renderer)
			.append(", connected ").append(yesNo(s.hooked)).append('\n');
		b.append("Player draws/sec: ").append(s.playerDrawsPerSec)
			.append(", drawn moved/sec: ").append(s.nudgedDrawsPerSec)
			.append(", hidden shown/sec: ").append(s.revealedDrawsPerSec)
			.append(", other-scene draws/sec: ").append(s.sceneMismatchesPerSec)
			.append(", players in other calls (should be 0): ").append(s.playersInOtherCalls)
			.append(", off-thread draws (should be 0): ").append(s.offThreadDraws)
			.append(", reveal errors: ").append(s.revealErrors)
			.append(", walk frames drawn: ").append(s.walkDraws)
			.append(", no walk (busy): ").append(s.walkSkippedBusy)
			.append(", no walk (animation not loaded): ").append(s.walkSkippedNoAnimation)
			.append(", held for confirmation: ").append(s.probeHeld)
			.append(", never confirmed: ").append(s.probeGaveUp)
			.append(", tile shape changes: ").append(s.shapeChanges)
			.append(", spot moves: ").append(s.spotMoves)
			.append(", no draws sustained: ").append(yesNo(s.noPlayerDrawsSustained))
			.append(", nothing moved sustained: ").append(yesNo(s.nothingMovedSustained)).append('\n');
		b.append("Nearby: ").append(s.nearby)
			.append(", standing still: ").append(s.still)
			.append(", stacked tiles: ").append(s.stackedTiles)
			.append(", being spread: ").append(s.moving)
			.append(", skipped ids: ").append(s.skippedIds)
			.append(", stacked but not shown by the game: ").append(s.unseenStacked).append('\n');
		b.append("Your tile: ").append(s.yourShape == null ? "not being spread" : s.yourShape).append('\n');
		b.append("Nearest spread tile: ").append(s.nearestTile == null ? "none" : s.nearestTile).append('\n');
		return b.toString();
	}

	private static String plural(int n, String word)
	{
		return n + " " + word + (n == 1 ? "" : "s");
	}

	private static String yesNo(boolean b)
	{
		return b ? "yes" : "no";
	}
}

