@PluginDescriptor(
	name = "Personal Space",
	description = "See the whole community: the one player you see on a tile is often a whole group, and this shows everyone standing there. Cosmetic only, and off wherever players can fight.",
	tags = {"stacked", "stacking", "unstack", "overlapping", "clipping", "crowded", "fashionscape", "fashion show", "outfits",
		"drip", "cosmetics", "gear", "other players", "show all players", "reveal", "grand exchange", "social", "hangout",
		"lively", "roleplay", "house party", "drop party", "clan events", "group photo", "screenshots", "content creator",
		"streamers", "shooting stars"}
)
public class PersonalSpacePlugin extends Plugin
{
	static final String VERSION = "1.8.14";

	private static final Logger log = LoggerFactory.getLogger(PersonalSpacePlugin.class);

	/** How often the sidebar is refreshed. */
	private static final long PANEL_REFRESH_NANOS = 500_000_000L;
	/** A problem has to last this many sidebar refreshes in a row before the status goes red. */
	private static final int SUSTAINED_REFRESHES = 3;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private PersonalSpaceConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	private final OffsetTable offsets = new OffsetTable();
	private final StackRegistry stacks = new StackRegistry();
	/** Who has which spot on each crowded tile, so crowds don't reshuffle. */
	/** Decides each tick which crowded tiles are spread and where everyone stands. */
	private final CrowdPlanner planner = new CrowdPlanner();
	private StackProbe probe;
	private final StillnessTracker stillness = new StillnessTracker();
	/** Tick number each player id was last counted on, to catch two players sharing an id. */
	private final int[] idSeenTick = new int[OffsetTable.CAPACITY];
	/** Tick on which each player was last found to be shown by the game. */
	private final int[] shownTick = new int[OffsetTable.CAPACITY];

	/** Our shim, while it is the client's installed draw callback. Null when nothing is hooked. Client thread. */
	private SpreadingDrawCallbacks wrapper;

	private volatile PersonalSpacePanel panel;
	private NavigationButton navButton;

	// ---- client-thread state -----------------------------------------------------------

	private long lastFrameNanos;
	private boolean warnedNoRenderer;
	private boolean warnedBadIds;
	private int tick;
	private final CombatWatch combat = new CombatWatch();

	/** What the last game tick found, for the sidebar. */
	private Snapshot.Gate gate = Snapshot.Gate.NOT_LOGGED_IN;
	private int nearby;
	private int still;
	private int stackedTiles;
	private int moving;
	private int skippedIds;
	private int unseen;
	private String nearestTile;
	private String yourShape;

	/** Sidebar rate bookkeeping. */
	private long lastPanelNanos;
	private SpreadingDrawCallbacks countedWrapper;
	private long lastPlayerDraws;
	private long lastNudgedDraws;
	private long lastRevealedDraws;
	private long lastSceneMismatches;
	private int noDrawsStreak;
	private int nothingMovedStreak;

	@Provides
	PersonalSpaceConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PersonalSpaceConfig.class);
	}

	@Override
	protected void startUp()
	{
		probe = new StackProbe(client, offsets, stacks);
		renderCallbackManager.register(probe);

		PersonalSpacePanel newPanel = new PersonalSpacePanel(configManager, config);
		BufferedImage icon = ImageUtil.loadImageResource(PersonalSpacePlugin.class, "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Personal Space")
			.icon(icon)
			.priority(7)
			.panel(newPanel)
			.build();
		clientToolbar.addNavigation(navButton);
		panel = newPanel;

		clientThread.invoke(() ->
		{
			lastFrameNanos = 0;
			lastPanelNanos = 0;
			warnedNoRenderer = false;
			warnedBadIds = false;
			countedWrapper = null;
			noDrawsStreak = 0;
			nothingMovedStreak = 0;
			resetTickState();
			probe.reset();
			// The shim itself is installed on the next frame, see ensureInstalled().
		});
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(probe);
		panel = null;
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		clientThread.invoke(() ->
		{
			uninstall();
			resetTickState();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!PersonalSpaceConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		PersonalSpacePanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::refreshControls);
		}
		if (PersonalSpaceConfig.KEY_ACTIVE.equals(event.getKey()) && !config.active())
		{
			// Pausing takes effect immediately, not on the next game tick.
			clientThread.invoke(this::resetTickState);
		}
	}

	// ---- per frame ---------------------------------------------------------------------

	@Subscribe
	public void onBeforeRender(BeforeRender event)
	{
		ensureInstalled();

		long now = System.nanoTime();
		float dt = lastFrameNanos == 0 ? 0f : (now - lastFrameNanos) / 1_000_000_000f;
		lastFrameNanos = now;
		offsets.advance(Math.min(dt, 0.25f));

		if (lastPanelNanos == 0 || now - lastPanelNanos >= PANEL_REFRESH_NANOS)
		{
			pushSnapshot(now);
		}
	}

	/**
	 * Keep our shim in front of whichever renderer is active. Renderers install themselves with
	 * setDrawCallbacks when they start and set it to null when they stop, so this is re-checked
	 * every frame rather than once at start-up. Cheap: one getter and a reference compare.
	 * Swapping is instant, except that if it lands while the game is part-way through loading a
	 * new area, the game restarts that load once; so it is only ever done when actually needed.
	 */
	private void ensureInstalled()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			// There is nothing to spread until you are in the world, and a renderer is at its most
			// delicate while it is starting up or shutting down: it creates and destroys its native
			// drawing context around then, and anything standing in front of it at that moment can be
			// handed calls it isn't ready for. So we stay out of the way until the world is up.
			uninstall();
			return;
		}

		DrawCallbacks current = client.getDrawCallbacks();
		if (current == null)
		{
			// No GPU renderer running; the software renderer never calls draw callbacks.
			wrapper = null;
			return;
		}
		if (current == wrapper)
		{
			return;
		}

		DrawCallbacks target = current;
		if (current instanceof SpreadingDrawCallbacks)
		{
			// Never stack shims (e.g. one left behind by an earlier instance of this plugin).
			target = ((SpreadingDrawCallbacks) current).getDelegate();
		}
		wrapper = new SpreadingDrawCallbacks(client, offsets, stacks, probe, renderCallbackManager, target);
		client.setDrawCallbacks(wrapper);
		log.debug("Hooked draw callbacks in front of {}", target.getClass().getName());
	}

	private void uninstall()
	{
		if (wrapper != null && client.getDrawCallbacks() == wrapper)
		{
			client.setDrawCallbacks(wrapper.getDelegate());
			log.debug("Restored draw callbacks to {}", wrapper.getDelegate().getClass().getName());
		}
		wrapper = null;
	}

	// ---- per game tick -----------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			resetTickState();
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			probe.reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tick++;
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			resetTickState();
			return;
		}
		Player local = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		if (local == null || wv == null)
		{
			resetTickState();
			return;
		}

		Snapshot.Gate newGate = safetyGate(local);
		if (newGate != Snapshot.Gate.SAFE || !config.active())
		{
			// Hard off: straight back to real positions, no easing, no exceptions.
			resetTickState();
			gate = newGate;
			return;
		}
		gate = newGate;

		if (wrapper == null && !warnedNoRenderer && client.getDrawCallbacks() == null)
		{
			warnedNoRenderer = true;
			client.addChatMessage(ChatMessageType.CONSOLE, "",
				"<col=ff8c00>Personal Space</col>: turn on the GPU plugin (or 117 HD) for this plugin to have any effect.", null);
		}

		probe.enabled = config.mode() == PersonalSpaceConfig.Mode.SPREAD;
		if (config.mode() == PersonalSpaceConfig.Mode.TEST_SHIFT_ME)
		{
			offsets.clearTargets();
			stacks.clear();
			offsets.setTarget(local.getId(), config.testOffset(), 0);
			nearby = countPlayers(wv);
			still = 0;
			stackedTiles = 0;
			moving = config.testOffset() > 0 ? 1 : 0;
			skippedIds = 0;
			unseen = 0;
			nearestTile = null;
			yourShape = null;
			return;
		}

		List<StackSpreader.Entry> entries = new ArrayList<>();
		List<StackSpreader.Placement> easingBack = new ArrayList<>();
		int nearbyCount = 0;
		int skipped = 0;
		int cycle = client.getGameCycle();
		for (Player p : wv.players())
		{
			if (p == null)
			{
				continue;
			}
			nearbyCount++;
			int id = p.getId();
			if (id < 0 || id >= OffsetTable.CAPACITY || idSeenTick[id] == tick)
			{
				// Out of range, or a second player with the same id this tick: offsets are keyed
				// by id, so such a player can't be moved safely. Should never happen.
				skipped++;
				if (!warnedBadIds)
				{
					warnedBadIds = true;
					log.warn("Skipping player with unusable id {}", id);
				}
				continue;
			}
			idSeenTick[id] = tick;

			LocalPoint lp = p.getLocalLocation();
			WorldPoint wp = p.getWorldLocation();
			if (lp == null || wp == null)
			{
				continue;
			}
			long tileKey = StackRegistry.key(wp.getPlane(), lp.getSceneX(), lp.getSceneY());
			boolean centred = StillnessTracker.isCentred(lp.getX(), lp.getY());
			boolean standingStill = stillness.observe(id, tileKey, centred, tick);
			if (!standingStill || p.isDead())
			{
				if (centred && offsets.isOffset(id))
				{
					// Dropped out of a ring but still on the tile: keep drawing them while they
					// ease back to the middle, instead of vanishing on the spot.
					easingBack.add(new StackSpreader.Placement(id, tileKey, 0, 0));
				}
				continue;
			}
			if (probe.isShown(id, p, cycle) && probe.othersAllow(renderCallbackManager, p))
			{
				shownTick[id] = tick;
			}
			entries.add(new StackSpreader.Entry(id, tileKey, p == local, p.getCurrentOrientation()));
		}

		planner.smallGroupsClose = config.smallGroupsClose();
		planner.pose = config.pose();
		planner.arrangement = config.arrangement();
		CrowdPlanner.Plan plan = planner.plan(entries, id -> shownTick[id] == tick, config.spacing(), config.maxStack(),
			config.arrangement() != PersonalSpaceConfig.Arrangement.CIRCLE, config.includeLocalPlayer(), tick, surroundings(wv));
		offsets.clearTargets();
		for (StackSpreader.Placement pl : plan.placements)
		{
			offsets.setTarget(pl.id, pl.dx, pl.dz);
		}
		// Everyone on a crowded tile goes in the table, not just those given a spot: the probe needs
		// them there to find out whether the game is willing to show them.
		List<StackSpreader.Placement> members = new ArrayList<>(plan.placements);
		members.addAll(plan.unplaced);
		members.addAll(easingBack);
		java.util.Set<Integer> unplacedIds = new java.util.HashSet<>();
		for (StackSpreader.Placement pl : plan.unplaced)
		{
			unplacedIds.add(pl.id);
		}
		stacks.rebuild(members, plan.curvedRows, unplacedIds, plan.fires, plan.poses);
		probe.forgetTilesNotIn(stacks);

		nearby = nearbyCount;
		still = entries.size();
		stackedTiles = StackSpreader.stackedTiles(entries);
		moving = plan.placements.size();
		skippedIds = skipped;
		unseen = plan.unseen;
		nearestTile = nearestTileReport(plan, local);
		yourShape = yourShapeReport(plan, local, config.spacing(), config.smallGroupsClose());
	}

	/** Why the effect must be off right now, or SAFE. */
	private Snapshot.Gate safetyGate(Player local)
	{
		if (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 1)
		{
			return Snapshot.Gate.WILDERNESS;
		}
		if (client.getVarbitValue(VarbitID.PVP_AREA_CLIENT) == 1)
		{
			return Snapshot.Gate.PVP_AREA;
		}
		EnumSet<WorldType> types = client.getWorldType();
		if (WorldType.isPvpWorld(types)
			|| types.contains(WorldType.PVP_ARENA)
			|| types.contains(WorldType.DEADMAN)
			|| types.contains(WorldType.TOURNAMENT_WORLD)
			|| types.contains(WorldType.BOUNTY))
		{
			return Snapshot.Gate.PVP_WORLD;
		}
		if (playersCanFight())
		{
			return Snapshot.Gate.PVP_ACTIVITY;
		}
		Actor target = local.getInteracting();
		boolean attacking = target instanceof NPC || target instanceof Player;
		boolean fighting = combat.update(local.getHealthRatio() != -1, attacking, attacking && target.getHealthRatio() != -1, tick);
		if (fighting && config.pauseInCombat())
		{
			return Snapshot.Gate.IN_COMBAT;
		}
		return Snapshot.Gate.SAFE;
	}

	/**
	 * True when the game offers to attack other players, as in Castle Wars, Soul Wars, Last Man
	 * Standing, Clan Wars or the Fight Pits, even on a normal world outside the Wilderness.
	 */
	private boolean playersCanFight()
	{
		String[] options = client.getPlayerOptions();
		if (options == null)
		{
			return false;
		}
		for (String option : options)
		{
			if (option == null)
			{
				continue;
			}
			String plain = Text.removeTags(option).trim();
			if (plain.equalsIgnoreCase("Attack") || plain.equalsIgnoreCase("Fight"))
			{
				return true;
			}
		}
		return false;
	}

	/** Everyone back to their real spot immediately and forget what the last tick found. Client thread. */
	private void resetTickState()
	{
		if (probe != null)
		{
			probe.enabled = false;
		}
		offsets.snapAllToZero();
		stacks.clear();
		planner.clear();
		stillness.clear();
		gate = client.getGameState() == GameState.LOGGED_IN ? gate : Snapshot.Gate.NOT_LOGGED_IN;
		nearby = 0;
		still = 0;
		stackedTiles = 0;
		moving = 0;
		skippedIds = 0;
		unseen = 0;
		nearestTile = null;
		yourShape = null;
	}

	/** Client thread. The world around crowded tiles; the collision map is only read if a tile needs it. */
	private CrowdPlanner.Surroundings surroundings(WorldView wv)
	{
		return new CrowdPlanner.Surroundings()
		{
			private CollisionTerrain collision;

			private CollisionTerrain collision()
			{
				if (collision == null)
				{
					collision = terrain(wv);
				}
				return collision;
			}

			@Override
			public boolean canStand(long tile, int dx, int dz)
			{
				int x = StackRegistry.sceneX(tile) * 128 + 64;
				int z = StackRegistry.sceneY(tile) * 128 + 64;
				return collision().canStand(StackRegistry.plane(tile), x, z, x + dx, z + dz);
			}

			@Override
			public boolean facesObstacle(long tile, double angle)
			{
				return collision().facesObstacle(StackRegistry.plane(tile), StackRegistry.sceneX(tile), StackRegistry.sceneY(tile), angle);
			}

			@Override
			public boolean isCounter(long tile, double angle)
			{
				return collision().isCounter(StackRegistry.plane(tile), StackRegistry.sceneX(tile), StackRegistry.sceneY(tile), angle);
			}

			@Override
			public List<int[]> firesNear(long tile)
			{
				List<int[]> out = new ArrayList<>(1);
				for (int east = -1; east <= 1; east++)
				{
					for (int north = -1; north <= 1; north++)
					{
						if (hasFire(wv, StackRegistry.plane(tile), StackRegistry.sceneX(tile) + east, StackRegistry.sceneY(tile) + north))
						{
							out.add(new int[]{east, north});
						}
					}
				}
				return out;
			}

			@Override
			public boolean facesFire(long tile, double angle)
			{
				return PersonalSpacePlugin.this.facesFire(wv, StackRegistry.plane(tile), StackRegistry.sceneX(tile), StackRegistry.sceneY(tile), angle);
			}
		};
	}

	/**
	 * Plain words for the shape you are standing in, for the line under the sidebar's title, or null
	 * when your own tile isn't being spread. It also says why people are close when something other
	 * than the slider decided that, which is the question the sidebar can't otherwise answer.
	 */
	private static String yourShapeReport(CrowdPlanner.Plan plan, Player local, int slider, boolean autoSpace)
	{
		LocalPoint lp = local.getLocalLocation();
		WorldPoint wp = local.getWorldLocation();
		if (lp == null || wp == null)
		{
			return null;
		}
		CrowdPlanner.TileReport yours = plan.tiles.get(StackRegistry.key(wp.getPlane(), lp.getSceneX(), lp.getSceneY()));
		if (yours == null)
		{
			return null;
		}
		String shape = yours.shape;
		String what;
		if (shape.startsWith("counter row"))
		{
			what = "a row along the counter or wall";
		}
		else if (shape.startsWith("line"))
		{
			what = "a line";
		}
		else if (shape.contains("fire"))
		{
			what = "a ring round the fire";
		}
		else if (shape.startsWith("curved row"))
		{
			what = "a curve round what you're facing";
		}
		else
		{
			what = "a ring";
		}
		String why = "";
		if (shape.contains("squeezed"))
		{
			why = ", squeezed for room";
		}
		else if (autoSpace && yours.spacing < slider)
		{
			why = ", kept close by Auto-space";
		}
		return "You're in " + what + why;
	}

	/** What was decided for the spread tile nearest to you, for the report; null if none is near. */
	private static String nearestTileReport(CrowdPlanner.Plan plan, Player local)
	{
		LocalPoint lp = local.getLocalLocation();
		WorldPoint wp = local.getWorldLocation();
		if (lp == null || wp == null)
		{
			return null;
		}
		Long nearest = null;
		int nearestDistance = Integer.MAX_VALUE;
		for (long tile : plan.tiles.keySet())
		{
			if (StackRegistry.plane(tile) != wp.getPlane())
			{
				continue;
			}
			int distance = Math.max(Math.abs(StackRegistry.sceneX(tile) - lp.getSceneX()),
				Math.abs(StackRegistry.sceneY(tile) - lp.getSceneY()));
			if (distance < nearestDistance || (distance == nearestDistance && tile < nearest))
			{
				nearest = tile;
				nearestDistance = distance;
			}
		}
		return nearest == null ? null : plan.tiles.get(nearest) + ", " + nearestDistance + " tiles from you";
	}

	/** Client thread. True if the tile a row is facing has a fire on it. */
	private boolean facesFire(WorldView wv, int plane, int sceneX, int sceneY, double angle)
	{
		return hasFire(wv, plane, sceneX + (int) Math.round(-Math.sin(angle)), sceneY + (int) Math.round(-Math.cos(angle)));
	}

	/** Client thread. True if this scene tile has a fire on it. */
	private boolean hasFire(WorldView wv, int plane, int x, int y)
	{
		Scene scene = wv.getScene();
		if (scene == null)
		{
			return false;
		}
		Tile[][][] tiles = scene.getTiles();
		if (tiles == null || plane < 0 || plane >= tiles.length || x < 0 || x >= tiles[plane].length
			|| y < 0 || y >= tiles[plane][x].length || tiles[plane][x][y] == null)
		{
			return false;
		}
		for (GameObject object : tiles[plane][x][y].getGameObjects())
		{
			if (object == null)
			{
				continue;
			}
			ObjectComposition def = client.getObjectDefinition(object.getId());
			if (def != null && def.getImpostorIds() != null)
			{
				def = def.getImpostor();
			}
			if (def != null && StackSpreader.isFireName(def.getName()))
			{
				return true;
			}
		}
		return false;
	}

	/** The game's walkability map for the current area, so nobody is drawn inside a booth or wall. */
	private static CollisionTerrain terrain(WorldView wv)
	{
		CollisionData[] maps = wv.getCollisionMaps();
		int[][][] flags = new int[4][][];
		if (maps != null)
		{
			for (int plane = 0; plane < Math.min(4, maps.length); plane++)
			{
				flags[plane] = maps[plane] == null ? null : maps[plane].getFlags();
			}
		}
		return new CollisionTerrain(flags);
	}

	private static int countPlayers(WorldView wv)
	{
		int n = 0;
		for (Player p : wv.players())
		{
			if (p != null)
			{
				n++;
			}
		}
		return n;
	}

	// ---- sidebar -----------------------------------------------------------------------

	/** Client thread. Capture the current state and hand it to the sidebar. */
	private void pushSnapshot(long now)
	{
		PersonalSpacePanel p = panel;
		if (p == null)
		{
			return;
		}

		Snapshot s = new Snapshot();
		s.active = config.active();
		s.arrangement = config.arrangement();
		s.mode = config.mode();
		s.spacing = config.spacing();
		s.maxStack = config.maxStack();
		s.includeLocal = config.includeLocalPlayer();
		s.smallGroupsClose = config.smallGroupsClose();
		s.pauseInCombat = config.pauseInCombat();
		s.pose = config.pose();
		s.testOffset = config.testOffset();

		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		s.gate = loggedIn ? gate : Snapshot.Gate.NOT_LOGGED_IN;

		DrawCallbacks current = client.getDrawCallbacks();
		SpreadingDrawCallbacks w = wrapper;
		s.hooked = w != null && current == w;
		s.renderer = current == null ? null : rendererName(s.hooked ? w.getDelegate() : current);

		double seconds = lastPanelNanos == 0 ? 0 : (now - lastPanelNanos) / 1_000_000_000.0;
		boolean ratesKnown = w != null && w == countedWrapper && seconds > 0;
		if (ratesKnown)
		{
			s.playerDrawsPerSec = perSecond(w.playerDraws - lastPlayerDraws, seconds);
			s.nudgedDrawsPerSec = perSecond(w.nudgedDraws - lastNudgedDraws, seconds);
			s.revealedDrawsPerSec = perSecond(w.revealedDraws - lastRevealedDraws, seconds);
			s.sceneMismatchesPerSec = perSecond(w.sceneMismatches - lastSceneMismatches, seconds);
		}
		if (w != null)
		{
			s.playersInOtherCalls = w.playersInOtherCalls;
			s.offThreadDraws = w.offThreadDraws;
			s.revealErrors = w.revealErrors;
			s.walkDraws = w.walkDraws;
			s.walkSkippedBusy = w.walkSkippedBusy;
			s.walkSkippedNoAnimation = w.walkSkippedNoAnimation;
		}
		countedWrapper = w;
		if (w != null)
		{
			lastPlayerDraws = w.playerDraws;
			lastNudgedDraws = w.nudgedDraws;
			lastRevealedDraws = w.revealedDraws;
			lastSceneMismatches = w.sceneMismatches;
		}
		lastPanelNanos = now;

		StackProbe pr = probe;
		if (pr != null)
		{
			s.probeHeld = pr.heldTotal;
			s.probeGaveUp = pr.gaveUpTotal;
		}
		s.shapeChanges = planner.shapeChanges();
		s.spotMoves = planner.spotMoves();
		s.unseenStacked = unseen;
		s.nearestTile = nearestTile;
		s.yourShape = yourShape;
		s.nearby = nearby;
		s.still = still;
		s.stackedTiles = stackedTiles;
		s.moving = moving;
		s.skippedIds = skippedIds;

		boolean effectShouldRun = s.active && loggedIn && s.gate == Snapshot.Gate.SAFE && s.hooked && ratesKnown;
		noDrawsStreak = effectShouldRun && s.playerDrawsPerSec == 0 ? noDrawsStreak + 1 : 0;
		nothingMovedStreak = effectShouldRun && s.moving > 0 && s.nudgedDrawsPerSec + s.revealedDrawsPerSec == 0 ? nothingMovedStreak + 1 : 0;
		s.noPlayerDrawsSustained = noDrawsStreak >= SUSTAINED_REFRESHES;
		s.nothingMovedSustained = nothingMovedStreak >= SUSTAINED_REFRESHES;

		SwingUtilities.invokeLater(() -> p.update(s));
	}

	private static int perSecond(long count, double seconds)
	{
		return count <= 0 ? 0 : (int) Math.round(count / seconds);
	}

	private static String rendererName(DrawCallbacks callbacks)
	{
		String name = callbacks.getClass().getSimpleName();
		if (name.equals("GpuPlugin"))
		{
			return "GPU plugin";
		}
		if (name.toLowerCase().contains("hd"))
		{
			return "117 HD";
		}
		return name;
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Which players share each stacked tile, as worked out on the last game tick.
 *
 * <p>Why this exists: when several players stand still in the exact middle of one tile, the game
 * only draws the first of them each frame and skips the rest before any renderer sees them. So
 * when the renderer is asked to draw a player on a stacked tile, the draw shim looks the tile up
 * here and draws the hidden stackmates itself.
 *
 * <p>Tiles are keyed by scene coordinates (plane, scene x, scene y), because that is what the draw
 * call can see cheaply. The table is rebuilt once per tick on the client thread and swapped in as
 * a whole, so a reader never sees it half-built. Knows nothing about RuneLite; unit tested.
 */
final class StackRegistry
{
	private static final int[] NONE = new int[0];

	private volatile Map<Long, int[]> byTile = Collections.emptyMap();
	/** Tiles laid out as a curved row this tick. */
	private volatile java.util.Set<Long> curvedRows = Collections.emptySet();
	/** Players on a crowded tile who weren't given a spot this tick (past the limit, you staying put, or not shown yet). */
	private volatile java.util.Set<Integer> unplaced = Collections.emptySet();
	/** Tiles gathered round a fire, and where the fire is from the tile centre. */
	private volatile Map<Long, int[]> fires = Collections.emptyMap();
	/** Small groups posed to face each other or angled towards each other. */
	private volatile Map<Long, PersonalSpaceConfig.Pose> poses = Collections.emptyMap();

	static long key(int plane, int sceneX, int sceneY)
	{
		return ((long) (plane & 0xFF) << 40) | ((long) (sceneX & 0xFFFFF) << 20) | (sceneY & 0xFFFFF);
	}

	static int plane(long key)
	{
		return (int) ((key >> 40) & 0xFF);
	}

	static int sceneX(long key)
	{
		return (int) ((key >> 20) & 0xFFFFF);
	}

	static int sceneY(long key)
	{
		return (int) (key & 0xFFFFF);
	}

	/** Replace the table with the tiles and members in these placements (placement order is kept). */
	void rebuild(List<StackSpreader.Placement> placements, java.util.Set<Long> curvedRowTiles)
	{
		rebuild(placements, curvedRowTiles, Collections.emptySet());
	}

	void rebuild(List<StackSpreader.Placement> members, java.util.Set<Long> curvedRowTiles, java.util.Set<Integer> unplacedIds)
	{
		rebuild(members, curvedRowTiles, unplacedIds, Collections.emptyMap());
	}

	void rebuild(List<StackSpreader.Placement> members, java.util.Set<Long> curvedRowTiles, java.util.Set<Integer> unplacedIds,
		Map<Long, int[]> fireByTile)
	{
		rebuild(members, curvedRowTiles, unplacedIds, fireByTile, Collections.emptyMap());
	}

	void rebuild(List<StackSpreader.Placement> members, java.util.Set<Long> curvedRowTiles, java.util.Set<Integer> unplacedIds,
		Map<Long, int[]> fireByTile, Map<Long, PersonalSpaceConfig.Pose> poseByTile)
	{
		curvedRows = curvedRowTiles == null ? Collections.emptySet() : new java.util.HashSet<>(curvedRowTiles);
		unplaced = unplacedIds == null ? Collections.emptySet() : new java.util.HashSet<>(unplacedIds);
		fires = fireByTile == null ? Collections.emptyMap() : new HashMap<>(fireByTile);
		poses = poseByTile == null ? Collections.emptyMap() : new HashMap<>(poseByTile);
		rebuild(members);
	}

	/** Where the fire this tile's crowd is gathered round is, from the tile centre, or null. */
	int[] fireAt(long tileKey)
	{
		return fires.get(tileKey);
	}

	/**
	 * Which way a player drawn at (dx, dz) from this tile's centre should face: towards the fire the
	 * crowd is gathered round, round towards what a curved row faces, posed for a small group, or
	 * just their own facing.
	 */
	int drawOrientation(long tileKey, int orientation, int dx, int dz)
	{
		int[] fire = fires.get(tileKey);
		if (fire != null)
		{
			return StackSpreader.faceTowards(orientation, dx, dz, fire[0], fire[1]);
		}
		if (curvedRows.contains(tileKey))
		{
			return StackSpreader.faceSameSpot(orientation, dx, dz);
		}
		PersonalSpaceConfig.Pose pose = poses.get(tileKey);
		if (pose == PersonalSpaceConfig.Pose.FACING)
		{
			return StackSpreader.faceTowards(orientation, dx, dz, 0, 0);
		}
		if (pose == PersonalSpaceConfig.Pose.ANGLED)
		{
			return StackSpreader.halfway(orientation, StackSpreader.faceTowards(orientation, dx, dz, 0, 0));
		}
		return orientation;
	}

	/** True if this player is on a crowded tile but wasn't given a spot this tick. */
	boolean isUnplaced(int id)
	{
		return unplaced.contains(id);
	}

	/** True if this tile is a curved row, whose players turn to face what the row is facing. */
	boolean isCurvedRow(long tileKey)
	{
		return curvedRows.contains(tileKey);
	}

	void rebuild(List<StackSpreader.Placement> placements)
	{
		if (placements.isEmpty())
		{
			byTile = Collections.emptyMap();
			return;
		}
		Map<Long, List<Integer>> grouped = new LinkedHashMap<>();
		for (StackSpreader.Placement p : placements)
		{
			grouped.computeIfAbsent(p.tile, k -> new ArrayList<>(5)).add(p.id);
		}
		Map<Long, int[]> table = new HashMap<>(grouped.size() * 2);
		for (Map.Entry<Long, List<Integer>> e : grouped.entrySet())
		{
			List<Integer> ids = e.getValue();
			int[] arr = new int[ids.size()];
			for (int i = 0; i < arr.length; i++)
			{
				arr[i] = ids.get(i);
			}
			table.put(e.getKey(), arr);
		}
		byTile = table;
	}

	void clear()
	{
		curvedRows = Collections.emptySet();
		unplaced = Collections.emptySet();
		fires = Collections.emptyMap();
		poses = Collections.emptyMap();
		byTile = Collections.emptyMap();
	}

	boolean isEmpty()
	{
		return byTile.isEmpty();
	}

	/** Ids of the players placed on this tile, or an empty array. Never null. */
	int[] membersAt(long tileKey)
	{
		int[] ids = byTile.get(tileKey);
		return ids == null ? NONE : ids;
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The geometry of a crowded tile: where its spots are, which way a group faces, and which way a
 * moved player should turn. Knows nothing about RuneLite so it can be unit tested on its own.
 *
 * <p>Two shapes (chosen by {@link ShapeMemory}):
 * <ul>
 * <li><b>Row</b>: side by side in front of the thing everyone faces. Around an anvil, range or fire
 * the row curves round it; along a bank counter it runs straight.</li>
 * <li><b>Crowd</b>: rings around the tile, for players facing every which way.</li>
 * </ul>
 */
final class StackSpreader
{
	/** Orientation units in a full turn, as used by the game. 0 faces south, 512 west, 1024 north, 1536 east. */
	static final int FULL_TURN = 2048;

	/** How closely a group's facings must agree to count as "facing the same way" (about 25 degrees either side). */
	static final double SAME_FACING = 0.9;
	/** A tile already in a row stays a row until facings disagree by more than this (about 45 degrees), so it doesn't flip back and forth. */
	static final double STILL_SAME_FACING = 0.7;

	/** How far ahead of a player the thing they're facing is assumed to be: the next tile over. */
	static final int LOOK_AHEAD = 128;

	/** Most a curved row turns between neighbours is this divided by {@link #ARC_REACH}: 28 degrees. */
	static final double MAX_ARC = Math.toRadians(70);
	/**
	 * How far round what everyone faces a curved row may wrap either side of straight ahead
	 * (135 degrees). People gather all the way round a tree, fire or anvil before anyone has to stand
	 * behind someone else, where an axe or hammer would look like it's swinging at them.
	 */
	static final double WRAP_ARC = Math.toRadians(135);

	/** Most players in one straight row before the next row starts. */
	static final int ROW_WIDTH = 8;
	/** Most players in one curved row before the next row starts. */
	static final int CURVED_ROW_WIDTH = 10;
	private static final int ROWS = 3;
	/** Furthest a row stands behind the row in front, whatever the spacing: just under a tile. */
	static final int ROW_DEPTH = 112;
	/** Spacings used to size the largest turn between curved-row neighbours; see {@link #MAX_ARC}. */
	static final double ARC_REACH = 2.5;
	/** Furthest a straight row reaches either side of the middle, in spacings: a little further, so a row blocked on one side can grow along the other. */
	static final double STRAIGHT_REACH = 3.5;
	/** Crowd spots, best first: an inner ring, the middle, then an outer ring. Opposite sides alternate so any number looks balanced. */
	private static final double[] INNER_RING = {0, 180, 120, 300, 60, 240};
	private static final double[] OUTER_RING = {30, 210, 150, 330, 90, 270, 0, 180, 60, 240, 120, 300};
	static final int CROWD_PATTERN_SIZE = INNER_RING.length + 1 + OUTER_RING.length;

	/** Where a spot can be, relative to the tile centre. */
	interface SpotCheck
	{
		boolean canStand(int dx, int dz);
	}

	/** Furthest a player is placed from the tile centre along a line, in local units (three tiles). */
	static final int MAX_LINE_EXTENT = 384;
	/** Furthest back from its middle a bowed counter row reaches, in local units. */
	static final int MAX_BOW = 48;
	/**
	 * Steepest a bow gets. A row behind stands half a spacing along from the one in front, so a
	 * steeper curve than this would close the gap between them until the two of them touched.
	 */
	static final double BOW_SLOPE = 0.45;

	/** One standing-still player on a tile. */
	static final class Entry
	{
		final int id;
		final long tile;
		final boolean local;
		/** Facing in game orientation units, or -1 if unknown. */
		final int orientation;

		Entry(int id, long tile, boolean local)
		{
			this(id, tile, local, -1);
		}

		Entry(int id, long tile, boolean local, int orientation)
		{
			this.id = id;
			this.tile = tile;
			this.local = local;
			this.orientation = orientation;
		}
	}

	/** Where one player should be drawn relative to their real spot, in local units (x east, z north). */
	static final class Placement
	{
		final int id;
		final long tile;
		final int dx;
		final int dz;

		Placement(int id, long tile, int dx, int dz)
		{
			this.id = id;
			this.tile = tile;
			this.dx = dx;
			this.dz = dz;
		}
	}

	private StackSpreader()
	{
	}

	/**
	 * The usable spots for a tile, best first, at most {@code capacity} of them. The pattern never
	 * depends on how many players there are, so adding or removing a player never moves anyone
	 * else's spot. Spots a player couldn't stand on (a booth, stall, anvil or wall) are skipped.
	 *
	 * <p>Rows: a front row, then a row behind it, then another, up to {@link #ROW_WIDTH} usable spots
	 * each in a straight row and {@link #CURVED_ROW_WIDTH} in a curved one, which wraps up to
	 * {@link #WRAP_ARC} round what everyone faces before a row behind is started. The front row starts half a spacing either side of the middle, so two players share the
	 * space in front of what they face evenly, and it grows outwards from there. When someone who
	 * stays put stands in the middle, the front row leaves them a full spacing of room instead. Each
	 * row behind stands in the gaps of the row in front. A row curves around what everyone faces,
	 * except at a counter ({@code straight}), where it runs straight along it.
	 *
	 * <p>Crowds: an inner ring, the middle, then an outer ring.
	 */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity, SpotCheck check)
	{
		return spots(row, straight, angle, middleTaken, spacing, capacity, check, LOOK_AHEAD);
	}

	/** As above, on a curve of {@code arcRadius}; see {@link #arcRadius(int, boolean)}. */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity,
		SpotCheck check, int arcRadius)
	{
		return spots(row, straight, angle, middleTaken, spacing, capacity, check, arcRadius, false);
	}

	/** As above; {@code bow} curves a straight row gently round what it stands along. */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity,
		SpotCheck check, int arcRadius, boolean bow)
	{
		return spots(row, straight, angle, middleTaken, spacing, capacity, check, arcRadius, bow, WRAP_ARC);
	}

	/** As above, wrapping {@code wrap} round what everyone faces before a row behind is started. */
	static List<int[]> spots(boolean row, boolean straight, double angle, boolean middleTaken, int spacing, int capacity,
		SpotCheck check, int arcRadius, boolean bow, double wrap)
	{
		List<int[]> out = new ArrayList<>(capacity);
		if (!row)
		{
			for (int i = 0; i < CROWD_PATTERN_SIZE && out.size() < capacity; i++)
			{
				if (middleTaken && i == INNER_RING.length)
				{
					continue;
				}
				int[] spot = crowdSpot(i, spacing);
				if (check == null || check.canStand(spot[0], spot[1]))
				{
					out.add(spot);
				}
			}
			return out;
		}

		double reach = straight ? STRAIGHT_REACH : wrap / curvedTurn(spacing, arcRadius) + 1e-9;
		int width = straight ? ROW_WIDTH : CURVED_ROW_WIDTH;
		// Which side of the middle a row fills first. The ring pattern always starts on the east
		// side, so a row does too where it can: a pair then keeps its places when their tile changes
		// between a ring and a row, instead of the two of them swapping sides for no reason.
		double alongX = -Math.cos(angle);
		int first = (Math.abs(alongX) > 1e-9 ? alongX : Math.sin(angle)) >= 0 ? 1 : -1;
		for (int rowNumber = 0; rowNumber < ROWS && out.size() < capacity; rowNumber++)
		{
			// Rows take turns between spots off the middle line and spots on it, so each row
			// stands in the gaps of the one in front.
			boolean offMiddle = (rowNumber % 2 == 0) != middleTaken;
			int inRow = 0;
			for (double step = offMiddle ? 0.5 : 0; step <= reach && inRow < width && out.size() < capacity; step++)
			{
				for (int side = 0; side < (step == 0 ? 1 : 2) && inRow < width && out.size() < capacity; side++)
				{
					if (step == 0 && rowNumber == 0 && middleTaken)
					{
						continue;
					}
					int[] spot = rowSpot(rowNumber, first * (side == 0 ? step : -step), straight, angle, spacing, arcRadius, bow);
					if (spot != null && (check == null || check.canStand(spot[0], spot[1])))
					{
						out.add(spot);
						inRow++;
					}
				}
			}
		}
		return out;
	}

	/**
	 * The spot {@code step} spacings along row {@code rowNumber} (0 is the front row), relative to the
	 * tile centre, or null if that is further out than a row may reach.
	 *
	 * <p>A curved row keeps everyone the same distance from what they face ({@link #LOOK_AHEAD}
	 * ahead of the tile centre, plus a row depth for each row behind). Front-row neighbours are about
	 * {@code spacing} apart along the curve, but never more than {@link #MAX_ARC} / {@link #ARC_REACH}
	 * round from each other; rows behind
	 * keep the same angle between neighbours, so their half-step offsets land in the gaps. A straight
	 * row runs sideways across the facing, each row behind a row depth further back.
	 */
	static int[] rowSpot(int rowNumber, double step, boolean straight, double angle, int spacing)
	{
		return rowSpot(rowNumber, step, straight, angle, spacing, LOOK_AHEAD);
	}

	/** As above, on a curve of {@code arcRadius}; see {@link #arcRadius(int, boolean)}. */
	static int[] rowSpot(int rowNumber, double step, boolean straight, double angle, int spacing, int arcRadius)
	{
		return rowSpot(rowNumber, step, straight, angle, spacing, arcRadius, false);
	}

	/** As above; {@code bow} curves a straight row gently round what it stands along. */
	static int[] rowSpot(int rowNumber, double step, boolean straight, double angle, int spacing, int arcRadius, boolean bow)
	{
		double fwdX = -Math.sin(angle);
		double fwdZ = -Math.cos(angle);
		// A row behind stands half a spacing along from the one in front, so where the row in front
		// has bowed away from it the gap between the two closes. Give every row behind that much
		// more depth and the two of them stay exactly as far apart as they were before the bow.
		double depth = rowNumber * (Math.min(spacing, ROW_DEPTH) + (bow ? BOW_SLOPE * spacing / 2 : 0));
		if (straight)
		{
			double along = step * spacing;
			if (Math.abs(along) > MAX_LINE_EXTENT)
			{
				return null;
			}
			double back = depth + (bow ? bowBack(along) : 0);
			double x = fwdZ * along - fwdX * back;
			double z = -fwdX * along - fwdZ * back;
			return new int[]{(int) Math.round(x), (int) Math.round(z)};
		}
		double radius = arcRadius + depth;
		double phi = step * curvedTurn(spacing, arcRadius);
		double focusX = fwdX * arcRadius;
		double focusZ = fwdZ * arcRadius;
		double backX = -fwdX * radius;
		double backZ = -fwdZ * radius;
		double x = focusX + backX * Math.cos(phi) - backZ * Math.sin(phi);
		double z = focusZ + backX * Math.sin(phi) + backZ * Math.cos(phi);
		if (arcRadius > LOOK_AHEAD && Math.hypot(x, z) > MAX_LINE_EXTENT)
		{
			// A curve opened out by the slider still reaches no further than a row does.
			return null;
		}
		return new int[]{(int) Math.round(x), (int) Math.round(z)};
	}

	/**
	 * How far back from the middle of a bowed row a spot {@code along} it stands, so a crowd at a
	 * bank booth curves round it the way one round an anvil does, instead of standing in a flat line.
	 * It is the same circle a curved row hugs, flattened out at {@link #MAX_BOW} so a wide row's ends
	 * don't curl back into the row behind.
	 */
	static int bowBack(double along)
	{
		// The circle, while it is shallow enough that the row behind keeps its gap over a half step,
		// then a straight taper at that same slope, then flat at MAX_BOW.
		double turn = BOW_SLOPE / Math.sqrt(1 + BOW_SLOPE * BOW_SLOPE);
		double straightFrom = LOOK_AHEAD * turn;
		double d = Math.abs(along);
		double back = d <= straightFrom
			? LOOK_AHEAD - Math.sqrt(LOOK_AHEAD * (double) LOOK_AHEAD - d * d)
			: LOOK_AHEAD - Math.sqrt(LOOK_AHEAD * (double) LOOK_AHEAD - straightFrom * straightFrom)
				+ BOW_SLOPE * (d - straightFrom);
		return (int) Math.round(Math.min(MAX_BOW, back));
	}

	/** The angle between neighbours in a curved row, in radians. */
	static double curvedTurn(int spacing)
	{
		return curvedTurn(spacing, LOOK_AHEAD);
	}

	/** The angle between neighbours in a curved row of {@code arcRadius}, in radians. */
	static double curvedTurn(int spacing, int arcRadius)
	{
		return Math.min((double) spacing / arcRadius, MAX_ARC / ARC_REACH);
	}

	/**
	 * The circle a curved row stands on. Normally {@link #LOOK_AHEAD}, so the curve hugs whatever
	 * everyone is facing: an anvil, a tree, a fire. Neighbours are then never more than
	 * {@link #MAX_ARC} / {@link #ARC_REACH} round from each other, which is about half a tile apart,
	 * however wide the spacing slider is set.
	 *
	 * <p>With {@code wide} - auto-spacing off, so the slider is in charge - the circle grows instead
	 * of the turn, until neighbours stand a full spacing apart. The curve opens out into a wide
	 * crescent rather than stopping at half a tile.
	 */
	static int arcRadius(int spacing, boolean wide)
	{
		return wide ? Math.max(LOOK_AHEAD, (int) Math.ceil(spacing / (MAX_ARC / ARC_REACH))) : LOOK_AHEAD;
	}

	/** Crowd spot {@code index}, relative to the tile centre: an inner ring, the middle, then an outer ring. */
	private static int[] crowdSpot(int index, int spacing)
	{
		if (index < INNER_RING.length)
		{
			return polar(0.8 * spacing, INNER_RING[index]);
		}
		if (index == INNER_RING.length)
		{
			return new int[]{0, 0};
		}
		return polar(Math.min(1.6 * spacing, MAX_LINE_EXTENT), OUTER_RING[index - INNER_RING.length - 1]);
	}

	private static int[] polar(double radius, double degrees)
	{
		double a = Math.toRadians(degrees);
		return new int[]{(int) Math.round(radius * Math.cos(a)), (int) Math.round(radius * Math.sin(a))};
	}

	/** True for the names of fires people gather round: a fire someone lit, a campfire, a fire pit. Not fireplaces. */
	static boolean isFireName(String name)
	{
		if (name == null)
		{
			return false;
		}
		String n = name.toLowerCase();
		return n.contains("fire") && !n.contains("fireplace");
	}

	/** How many tiles have two or more of the given players on them. */
	static int stackedTiles(List<Entry> entries)
	{
		Map<Long, Integer> counts = new LinkedHashMap<>();
		int stacked = 0;
		for (Entry e : entries)
		{
			if (counts.merge(e.tile, 1, Integer::sum) == 2)
			{
				stacked++;
			}
		}
		return stacked;
	}

	/**
	 * The direction the whole group faces, in radians (game convention: 0 south, pi/2 west), or
	 * null if their facings are unknown or don't agree to at least {@code needed} (1 is identical).
	 */
	static Double sharedFacing(List<Entry> group, double needed)
	{
		double sumX = 0;
		double sumZ = 0;
		for (Entry e : group)
		{
			if (e.orientation < 0)
			{
				return null;
			}
			double a = toRadians(e.orientation);
			sumX += -Math.sin(a);
			sumZ += -Math.cos(a);
		}
		double agreement = Math.hypot(sumX, sumZ) / group.size();
		if (agreement < needed)
		{
			return null;
		}
		return Math.atan2(-sumX, -sumZ);
	}

	/**
	 * Which way a player moved by (dx, dz) should face to keep looking at the same spot they were
	 * looking at from their real position, {@link #LOOK_AHEAD} in front of them. So the players at
	 * the ends of a row at an anvil turn in towards the anvil instead of staring past it.
	 */
	static int faceSameSpot(int orientation, int dx, int dz)
	{
		if (dx == 0 && dz == 0)
		{
			return orientation;
		}
		double a = toRadians(orientation);
		double lookX = -Math.sin(a) * LOOK_AHEAD - dx;
		double lookZ = -Math.cos(a) * LOOK_AHEAD - dz;
		if (Math.hypot(lookX, lookZ) < 1)
		{
			return orientation;
		}
		return OffsetTable.facing(lookX, lookZ);
	}

	/**
	 * Which way a player drawn at (dx, dz) from the tile centre should face to look at the point
	 * (focusX, focusZ), also relative to the tile centre; {@code orientation} if they're standing on it.
	 */
	static int faceTowards(int orientation, int dx, int dz, int focusX, int focusZ)
	{
		double lookX = focusX - dx;
		double lookZ = focusZ - dz;
		if (Math.hypot(lookX, lookZ) < 1)
		{
			return orientation;
		}
		return OffsetTable.facing(lookX, lookZ);
	}

	/** The orientation halfway round from {@code from} to {@code to}, the short way. */
	static int halfway(int from, int to)
	{
		int diff = ((to - from) % FULL_TURN + FULL_TURN + FULL_TURN / 2) % FULL_TURN - FULL_TURN / 2;
		return ((from + diff / 2) % FULL_TURN + FULL_TURN) % FULL_TURN;
	}

	static double toRadians(int orientation)
	{
		return 2 * Math.PI * (((orientation % FULL_TURN) + FULL_TURN) % FULL_TURN) / FULL_TURN;
	}

}

package com.grant9008.personalspace;

/**
 * Per-player draw offsets in local units, indexed by player id, and how players move into them.
 *
 * <p>Targets are set once per game tick and moved toward once per frame, and the published
 * {@code outX}/{@code outZ} values are read from the renderer's drawTemp call. All three happen on
 * the client thread (checked against the RuneLite 1.12.38 client), so plain arrays are enough.
 *
 * <p>Players walk to their spot in a straight line at the game's walking pace. While a player is on
 * the way, {@link #isWalking} is true and {@link #walkSeconds}/{@link #walkOrientation} tell the draw
 * shim which walk frame to show and which way to face.
 */
final class OffsetTable
{
	/** RuneScape never has more than this many players in the scene. */
	static final int CAPACITY = 2048;

	/** Walking pace: the game's own, one tile (128 units) every 0.6 seconds. */
	static final float WALK_SPEED = 128f / 0.6f;
	/** Moves shorter than this just drift into place, with no walk animation, so small corrections don't look like shuffling. */
	static final float MIN_WALK_DISTANCE = 28f;

	private final float[] curX = new float[CAPACITY];
	private final float[] curZ = new float[CAPACITY];
	private final int[] tgtX = new int[CAPACITY];
	private final int[] tgtZ = new int[CAPACITY];
	private final int[] outX = new int[CAPACITY];
	private final int[] outZ = new int[CAPACITY];

	private final boolean[] walking = new boolean[CAPACITY];
	private final float[] walkTime = new float[CAPACITY];
	private final int[] walkFacing = new int[CAPACITY];

	/** Ids that currently have a non-zero target or are still moving back to zero. */
	private final int[] active = new int[CAPACITY];
	private final boolean[] isActive = new boolean[CAPACITY];
	private int activeCount;
	private int frame;

	int dx(int id)
	{
		return id >= 0 && id < CAPACITY ? outX[id] : 0;
	}

	int dz(int id)
	{
		return id >= 0 && id < CAPACITY ? outZ[id] : 0;
	}

	/** True while this player is drawn away from their real spot, including while moving back. */
	boolean isOffset(int id)
	{
		return id >= 0 && id < CAPACITY && (outX[id] != 0 || outZ[id] != 0);
	}

	/** True while this player is walking to (or back from) their spot. */
	boolean isWalking(int id)
	{
		return id >= 0 && id < CAPACITY && walking[id];
	}

	/** Seconds this player has been walking, to pick the walk animation frame. */
	float walkSeconds(int id)
	{
		return id >= 0 && id < CAPACITY ? walkTime[id] : 0f;
	}

	/** Which way a walking player faces, in game orientation units (0 south, 512 west, 1024 north, 1536 east). */
	int walkOrientation(int id)
	{
		return id >= 0 && id < CAPACITY ? walkFacing[id] : 0;
	}

	/** True if this player currently has somewhere other than their real spot to be. */
	boolean hasTarget(int id)
	{
		return id >= 0 && id < CAPACITY && isActive[id] && (tgtX[id] != 0 || tgtZ[id] != 0);
	}

	int targetX(int id)
	{
		return id >= 0 && id < CAPACITY ? tgtX[id] : 0;
	}

	int targetZ(int id)
	{
		return id >= 0 && id < CAPACITY ? tgtZ[id] : 0;
	}

	/** Counts frames; used to tell draws in the same frame apart. */
	int frame()
	{
		return frame;
	}

	/** Client thread. Zero every target before this tick's placements are applied. */
	void clearTargets()
	{
		for (int i = 0; i < activeCount; i++)
		{
			int id = active[i];
			tgtX[id] = 0;
			tgtZ[id] = 0;
		}
	}

	/** Client thread. */
	void setTarget(int id, int dx, int dz)
	{
		if (id < 0 || id >= CAPACITY)
		{
			return;
		}
		tgtX[id] = dx;
		tgtZ[id] = dz;
		if (!isActive[id] && (dx != 0 || dz != 0))
		{
			isActive[id] = true;
			active[activeCount++] = id;
		}
	}

	/** Client thread. Everyone back to their real spot immediately, no movement. Used for safety and shutdown. */
	void snapAllToZero()
	{
		for (int i = 0; i < activeCount; i++)
		{
			int id = active[i];
			curX[id] = 0f;
			curZ[id] = 0f;
			tgtX[id] = 0;
			tgtZ[id] = 0;
			outX[id] = 0;
			outZ[id] = 0;
			walking[id] = false;
			walkTime[id] = 0f;
			isActive[id] = false;
		}
		activeCount = 0;
	}

	/** Client thread, once per frame. Moves every active offset toward its target. */
	void advance(float dtSeconds)
	{
		frame++;
		for (int i = activeCount - 1; i >= 0; i--)
		{
			int id = active[i];
			walkTowardTarget(id, dtSeconds);
			outX[id] = Math.round(curX[id]);
			outZ[id] = Math.round(curZ[id]);
			if (tgtX[id] == 0 && tgtZ[id] == 0 && curX[id] == 0f && curZ[id] == 0f)
			{
				// Fully back home: drop it from the active list (swap-remove; the slot we pull in
				// from the end was already visited this pass).
				walking[id] = false;
				walkTime[id] = 0f;
				isActive[id] = false;
				active[i] = active[--activeCount];
			}
		}
	}

	private void walkTowardTarget(int id, float dt)
	{
		float ex = tgtX[id] - curX[id];
		float ez = tgtZ[id] - curZ[id];
		float dist = (float) Math.hypot(ex, ez);
		float stride = WALK_SPEED * dt;
		if (dist <= Math.max(stride, 0.5f))
		{
			curX[id] = tgtX[id];
			curZ[id] = tgtZ[id];
			walking[id] = false;
			walkTime[id] = 0f;
			return;
		}
		curX[id] += ex / dist * stride;
		curZ[id] += ez / dist * stride;
		if (!walking[id])
		{
			if (dist < MIN_WALK_DISTANCE)
			{
				return; // a small correction: drift, don't start a walk
			}
			walking[id] = true;
			walkTime[id] = 0f;
		}
		walkTime[id] += dt;
		walkFacing[id] = facing(ex, ez);
	}

	/** Game orientation for moving in direction (east, north): 0 south, 512 west, 1024 north, 1536 east. */
	static int facing(double east, double north)
	{
		double angle = Math.atan2(-east, -north);
		int o = (int) Math.round(angle * 1024 / Math.PI);
		return ((o % 2048) + 2048) % 2048;
	}
}

package com.grant9008.personalspace;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;

/**
 * Makes sure Personal Space only ever draws players the game itself is willing to show.
 *
 * <p>The game skips two kinds of player: ones hidden only because they share a tile with someone
 * (the stacks Personal Space spreads out), and ones the server hides on purpose, such as an
 * invisible Jagex moderator. The API can't tell these apart, so this callback watches the moment
 * the game adds each player to the scene. That step runs after the game has dropped server-hidden
 * players, so any player that reaches it is fine to draw. Such a player counts as "confirmed" for
 * a few seconds.
 *
 * <p>A player stacked behind someone else never reaches that step on their own. So while a
 * stacked tile has an unconfirmed player, this callback briefly tells the game not to draw the
 * confirmed players on that tile. RuneLite then lets the next player on the tile through, and it
 * gets confirmed and drawn. The players it held back are drawn by {@link SpreadingDrawCallbacks}
 * at their spots in the same frame, so nothing visibly changes. A player who never shows up within
 * a few frames is one the game won't draw, and is left hidden.
 *
 * <p>Client thread only: the game adds players to the scene and draws them on the client thread.
 */
final class StackProbe implements RenderCallback
{
	/** How long a confirmation lasts, in game cycles (20 ms each): 10 seconds. */
	static final int FRESH_CYCLES = 500;
	/** Frames to keep holding players back before deciding the missing one won't be drawn. */
	static final int MAX_PROBE_FRAMES = 3;
	/**
	 * Extra time a player still counts as shown when laying out a crowd. A stackmate's confirmation
	 * is only renewed on the frames the probe runs, so a short gap must not drop them from their
	 * crowd, which would make everyone walk in and back out. 10 seconds.
	 */
	static final int SHOWN_GRACE_CYCLES = 500;
	/** How long to leave a player alone after they failed to show up: 60 seconds. */
	static final int GIVE_UP_CYCLES = 3000;

	private static final int MAX_HIDDEN_PER_FRAME = 256;

	private static final class TileState
	{
		int frame = -1;
		boolean probing;
		int signature;
		int framesUsed;
	}

	private final Client client;
	private final OffsetTable offsets;
	private final StackRegistry stacks;

	private final Player[] confirmed = new Player[OffsetTable.CAPACITY];
	private final int[] confirmedCycle = new int[OffsetTable.CAPACITY];
	private final int[] leaveAloneUntil = new int[OffsetTable.CAPACITY];
	private final Map<Long, TileState> tiles = new HashMap<>();

	/** Players held back this frame, and their tiles, so the draw shim can draw them. */
	private int heldFrame = -1;
	private int heldCount;
	private final int[] heldIds = new int[MAX_HIDDEN_PER_FRAME];
	private final long[] heldTiles = new long[MAX_HIDDEN_PER_FRAME];

	/** Whether spreading is running right now. Set by the plugin each tick. */
	boolean enabled;
	/** Set by the draw shim while it asks other plugins about a player, so this callback stays out of it. */
	boolean asking;

	/** Diagnostics: total players held back. */
	long heldTotal;
	/** Diagnostics: players given up on because they never showed up. */
	long gaveUpTotal;

	StackProbe(Client client, OffsetTable offsets, StackRegistry stacks)
	{
		this.client = client;
		this.offsets = offsets;
		this.stacks = stacks;
	}

	@Override
	public boolean addEntity(Renderable renderable, boolean drawingUI)
	{
		if (drawingUI || asking || !(renderable instanceof Player) || !client.isClientThread())
		{
			return true;
		}
		Player player = (Player) renderable;
		int id = player.getId();
		if (id < 0 || id >= OffsetTable.CAPACITY)
		{
			return true;
		}

		int cycle = client.getGameCycle();
		boolean alreadyConfirmed = isConfirmed(id, player, cycle);
		confirmed[id] = player;
		confirmedCycle[id] = cycle;
		leaveAloneUntil[id] = 0;

		// A player who wasn't confirmed yet is drawn by the game as normal, which is exactly what
		// lets the rest of the tile be revealed around them.
		if (!enabled || !alreadyConfirmed || stacks.isEmpty())
		{
			return true;
		}
		LocalPoint lp = player.getLocalLocation();
		if (lp == null || !StillnessTracker.isCentred(lp.getX(), lp.getY()))
		{
			return true;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return true;
		}
		long key = StackRegistry.key(player.getWorldLocation().getPlane(), lp.getSceneX(), lp.getSceneY());
		int[] members = stacks.membersAt(key);
		if (members.length == 0 || !shouldProbe(key, members, wv, offsets.frame(), cycle))
		{
			return true;
		}

		hold(id, key, offsets.frame());
		return false;
	}

	/** True if this exact player object reached the scene recently, so the game is willing to draw them. */
	boolean isConfirmed(int id, Player player, int cycle)
	{
		return id >= 0 && id < OffsetTable.CAPACITY
			&& confirmed[id] == player
			&& cycle - confirmedCycle[id] <= FRESH_CYCLES;
	}

	/**
	 * True if the game has shown this player recently enough for them to count in a crowd. Players
	 * the game never shows (hidden by the server or by another plugin) never count, so they can't
	 * push a visible player aside next to nobody.
	 */
	boolean isShown(int id, Player player, int cycle)
	{
		return id >= 0 && id < OffsetTable.CAPACITY
			&& confirmed[id] == player
			&& cycle - confirmedCycle[id] <= FRESH_CYCLES + SHOWN_GRACE_CYCLES
			&& leaveAloneUntil[id] <= cycle;
	}

	/** Fill {@code out} with the ids held back this frame on the given tile; returns how many. */
	int heldOn(long tileKey, int frame, int[] out)
	{
		if (heldFrame != frame)
		{
			return 0;
		}
		int n = 0;
		for (int i = 0; i < heldCount && n < out.length; i++)
		{
			if (heldTiles[i] == tileKey)
			{
				out[n++] = heldIds[i];
			}
		}
		return n;
	}

	/** Forget everything, e.g. on logout or world hop. */
	void reset()
	{
		for (int i = 0; i < confirmed.length; i++)
		{
			confirmed[i] = null;
			confirmedCycle[i] = 0;
			leaveAloneUntil[i] = 0;
		}
		tiles.clear();
		heldFrame = -1;
		heldCount = 0;
	}

	/** Drop per-tile state for tiles that are no longer stacked. */
	void forgetTilesNotIn(StackRegistry registry)
	{
		tiles.keySet().removeIf(key -> registry.membersAt(key).length == 0);
	}

	/** Decided once per tile per frame, on the first confirmed player to arrive there. */
	private boolean shouldProbe(long key, int[] members, WorldView wv, int frame, int cycle)
	{
		TileState t = tiles.computeIfAbsent(key, k -> new TileState());
		if (t.frame == frame)
		{
			return t.probing;
		}
		t.frame = frame;

		int signature = 17;
		boolean waiting = false;
		for (int id : members)
		{
			if (id < 0 || id >= OffsetTable.CAPACITY || leaveAloneUntil[id] > cycle)
			{
				continue;
			}
			Player mate = wv.players().byIndex(id);
			if (mate == null || isConfirmed(id, mate, cycle))
			{
				continue;
			}
			waiting = true;
			signature = 31 * signature + id;
		}

		if (!waiting)
		{
			t.probing = false;
			t.signature = 0;
			t.framesUsed = 0;
			return false;
		}
		if (signature != t.signature)
		{
			t.signature = signature;
			t.framesUsed = 0;
		}
		if (t.framesUsed >= MAX_PROBE_FRAMES)
		{
			// They had their chance and never reached the scene: the game isn't drawing them.
			for (int id : members)
			{
				if (id >= 0 && id < OffsetTable.CAPACITY && leaveAloneUntil[id] <= cycle)
				{
					Player mate = wv.players().byIndex(id);
					if (mate != null && !isConfirmed(id, mate, cycle))
					{
						leaveAloneUntil[id] = cycle + GIVE_UP_CYCLES;
						gaveUpTotal++;
					}
				}
			}
			t.probing = false;
			t.signature = 0;
			t.framesUsed = 0;
			return false;
		}
		t.framesUsed++;
		t.probing = true;
		return true;
	}

	private void hold(int id, long key, int frame)
	{
		if (heldFrame != frame)
		{
			heldFrame = frame;
			heldCount = 0;
		}
		if (heldCount < MAX_HIDDEN_PER_FRAME)
		{
			heldIds[heldCount] = id;
			heldTiles[heldCount] = key;
			heldCount++;
		}
		heldTotal++;
	}

	/** Ask the other render callbacks (e.g. Entity Hider) whether a player may be drawn, without this one taking part. */
	boolean othersAllow(RenderCallbackManager manager, Player player)
	{
		if (manager == null)
		{
			return true;
		}
		asking = true;
		try
		{
			return manager.addEntity(player, false);
		}
		finally
		{
			asking = false;
		}
	}
}

package com.grant9008.personalspace;

/**
 * Answers "could a player be drawn standing here?" from the game's own walkability map, so
 * spread-out players never appear inside a bank booth, market stall, anvil, table or wall.
 *
 * <p>A spot counts as standable when its tile can be walked on, it can be reached from the
 * player's real tile by ordinary steps without passing through a wall, and it isn't pressed right
 * up against a blocked neighbour (models of booths and stalls hang over the tile edge).
 *
 * <p>Coordinates are scene local units: 128 per tile, x east, z north. Flags use the game's
 * CollisionDataFlag bits, copied here so this class stays free of RuneLite and unit testable.
 */
final class CollisionTerrain
{
	static final int BLOCK_NORTH_WEST = 1;
	static final int BLOCK_NORTH = 2;
	static final int BLOCK_NORTH_EAST = 4;
	static final int BLOCK_EAST = 8;
	static final int BLOCK_SOUTH_EAST = 16;
	static final int BLOCK_SOUTH = 32;
	static final int BLOCK_SOUTH_WEST = 64;
	static final int BLOCK_WEST = 128;
	/** Object, floor decoration or blocked floor: the tile can't be stood on at all. */
	static final int BLOCK_FULL = 256 | 262144 | 2097152;

	/** How close to a blocked edge a player may be drawn, in local units. */
	static final int EDGE_MARGIN = 26;

	private static final int TILE = 128;

	/** flags[plane][sceneX][sceneY]; a plane may be null if unknown. */
	private final int[][][] flags;

	CollisionTerrain(int[][][] flagsByPlane)
	{
		this.flags = flagsByPlane;
	}

	/** Whether a player standing at (fromX, fromZ) could be drawn at (x, z). */
	boolean canStand(int plane, int fromX, int fromZ, int x, int z)
	{
		int[][] f = plane >= 0 && plane < flags.length ? flags[plane] : null;
		if (f == null)
		{
			return true; // no map: don't restrict
		}
		int tx = floorDiv(x);
		int tz = floorDiv(z);
		if (!inside(f, tx, tz) || (f[tx][tz] & BLOCK_FULL) != 0)
		{
			return false;
		}

		// Walk from the real tile to the target tile one step at a time, like the game's pathing.
		int cx = floorDiv(fromX);
		int cz = floorDiv(fromZ);
		if (!inside(f, cx, cz))
		{
			return false;
		}
		int guard = 0;
		while ((cx != tx || cz != tz) && guard++ < 8)
		{
			int sx = Integer.signum(tx - cx);
			int sz = Integer.signum(tz - cz);
			if (!canStep(f, cx, cz, sx, sz))
			{
				return false;
			}
			cx += sx;
			cz += sz;
		}
		if (cx != tx || cz != tz)
		{
			return false;
		}

		// Keep clear of blocked edges so overhanging models don't swallow the player.
		int ox = x - tx * TILE;
		int oz = z - tz * TILE;
		if (ox < EDGE_MARGIN && !canStep(f, tx, tz, -1, 0))
		{
			return false;
		}
		if (ox > TILE - 1 - EDGE_MARGIN && !canStep(f, tx, tz, 1, 0))
		{
			return false;
		}
		if (oz < EDGE_MARGIN && !canStep(f, tx, tz, 0, -1))
		{
			return false;
		}
		return oz <= TILE - 1 - EDGE_MARGIN || canStep(f, tx, tz, 0, 1);
	}

	/**
	 * True if a player on this tile, facing {@code angle}, is facing something: the next tile that
	 * way can't be walked onto (an anvil, tree, booth, range or water) or there's a wall in between.
	 */
	boolean facesObstacle(int plane, int tileX, int tileY, double angle)
	{
		int[][] f = plane >= 0 && plane < flags.length ? flags[plane] : null;
		if (f == null || !inside(f, tileX, tileY))
		{
			return false;
		}
		int aheadX = (int) Math.round(-Math.sin(angle));
		int aheadZ = (int) Math.round(-Math.cos(angle));
		return (aheadX != 0 || aheadZ != 0) && !canStep(f, tileX, tileY, aheadX, aheadZ);
	}

	/**
	 * True if a player on this tile, facing {@code angle}, is up against something long: the way
	 * ahead is blocked (by a booth, counter or wall) for their tile and for the tiles either side.
	 * That's a bank counter or a row of booths, as opposed to a single anvil or range.
	 */
	boolean isCounter(int plane, int tileX, int tileY, double angle)
	{
		int[][] f = plane >= 0 && plane < flags.length ? flags[plane] : null;
		if (f == null)
		{
			return false;
		}
		int aheadX = (int) Math.round(-Math.sin(angle));
		int aheadZ = (int) Math.round(-Math.cos(angle));
		if ((aheadX != 0) == (aheadZ != 0))
		{
			return false; // facing diagonally: counters run along tile edges
		}
		int sideX = aheadZ != 0 ? 1 : 0;
		int sideZ = aheadX != 0 ? 1 : 0;
		return !canStep(f, tileX, tileY, aheadX, aheadZ)
			&& blockedAheadOf(f, tileX + sideX, tileY + sideZ, aheadX, aheadZ)
			&& blockedAheadOf(f, tileX - sideX, tileY - sideZ, aheadX, aheadZ);
	}

	/** The way ahead from this tile is blocked, or this tile itself can't be stood on. */
	private static boolean blockedAheadOf(int[][] f, int x, int z, int aheadX, int aheadZ)
	{
		if (!inside(f, x, z) || (f[x][z] & BLOCK_FULL) != 0)
		{
			return true;
		}
		return !canStep(f, x, z, aheadX, aheadZ);
	}

	/** Whether the game would let a player take one step from (x, z) by (sx, sz), each -1, 0 or 1. */
	static boolean canStep(int[][] f, int x, int z, int sx, int sz)
	{
		int nx = x + sx;
		int nz = z + sz;
		if (!inside(f, nx, nz) || (f[nx][nz] & BLOCK_FULL) != 0)
		{
			return false;
		}
		int from = f[x][z];
		int to = f[nx][nz];
		if (sx != 0 && sz != 0)
		{
			// Diagonal: the corner itself and both orthogonal routes must be clear.
			int outCorner = sx > 0 ? (sz > 0 ? BLOCK_NORTH_EAST : BLOCK_SOUTH_EAST) : (sz > 0 ? BLOCK_NORTH_WEST : BLOCK_SOUTH_WEST);
			int inCorner = sx > 0 ? (sz > 0 ? BLOCK_SOUTH_WEST : BLOCK_NORTH_WEST) : (sz > 0 ? BLOCK_SOUTH_EAST : BLOCK_NORTH_EAST);
			return (from & outCorner) == 0 && (to & inCorner) == 0
				&& canStep(f, x, z, sx, 0) && canStep(f, x, z, 0, sz)
				&& canStep(f, x + sx, z, 0, sz) && canStep(f, x, z + sz, sx, 0);
		}
		if (sx > 0)
		{
			return (from & BLOCK_EAST) == 0 && (to & BLOCK_WEST) == 0;
		}
		if (sx < 0)
		{
			return (from & BLOCK_WEST) == 0 && (to & BLOCK_EAST) == 0;
		}
		if (sz > 0)
		{
			return (from & BLOCK_NORTH) == 0 && (to & BLOCK_SOUTH) == 0;
		}
		if (sz < 0)
		{
			return (from & BLOCK_SOUTH) == 0 && (to & BLOCK_NORTH) == 0;
		}
		return true;
	}

	private static boolean inside(int[][] f, int x, int z)
	{
		return x >= 0 && z >= 0 && x < f.length && f[x] != null && z < f[x].length;
	}

	private static int floorDiv(int v)
	{
		return Math.floorDiv(v, TILE);
	}
}

package com.grant9008.personalspace;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Projection;
import net.runelite.api.Renderable;
import net.runelite.api.Scene;
import net.runelite.api.SceneTileModel;
import net.runelite.api.SceneTilePaint;
import net.runelite.api.Texture;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.callback.RenderCallbackManager;

/**
 * A thin shim installed in front of whatever renderer is active (the GPU plugin or 117 HD).
 *
 * <p>How the game draws players, checked against the RuneLite 1.12.38 client:
 * <ul>
 * <li>Players, NPCs and projectiles are "temporary" scene entities re-added every frame and drawn
 * through {@link #drawTemp}. {@code drawDynamic} only ever carries animated scenery and ground
 * items. (Version 0.1.0 hooked {@code drawDynamic} by mistake, so nothing moved.)</li>
 * <li>When several players stand still in the exact middle of one tile, the game adds only the
 * first of them to the scene each frame and skips the rest. That is why a stack looks like one
 * person, and why nudging draw calls alone can never reveal anyone.</li>
 * </ul>
 *
 * <p>So for a player draw on a stacked tile this shim does two things: it draws that player at its
 * own ring slot (if it has one), and then draws each hidden stackmate's model at that mate's slot,
 * reusing the same renderer call. Every other call is forwarded untouched. The real players, their
 * tiles, clickboxes, overhead text and chat bubbles are never modified. Hidden stackmates drawn
 * this way have no clickbox of their own, exactly as when the game hides them.
 *
 * <p>Every method of {@link DrawCallbacks} is overridden, including the ones with default bodies,
 * because a default body would silently swallow the call instead of forwarding it.
 *
 * <p>The counters are plain fields read by the plugin for the sidebar diagnostics.
 */
final class SpreadingDrawCallbacks implements DrawCallbacks
{
	private final Client client;
	private final OffsetTable offsets;
	private final StackRegistry stacks;
	private final StackProbe probe;
	private final RenderCallbackManager renderCallbacks;
	private final DrawCallbacks delegate;

	/** Players the renderer was asked to draw. */
	long playerDraws;
	/** Of those, how many we drew at a ring slot instead of their real spot. */
	long nudgedDraws;
	/** Hidden stackmates we drew ourselves. */
	long revealedDraws;
	/** Player draws for a scene other than the main one (e.g. on a boat); left alone. */
	long sceneMismatches;
	/** Players arriving through drawDynamic or the legacy draw call. Expected to stay 0. */
	long playersInOtherCalls;
	/** drawTemp calls made off the client thread. Expected to stay 0; such calls are passed through untouched. */
	long offThreadDraws;
	/** Errors while drawing a hidden stackmate (that mate is skipped for the frame). */
	long revealErrors;
	/** Player models drawn mid-step with their walk animation. */
	long walkDraws;
	/** Moving players drawn without walk frames because they were busy with an emote or action. */
	long walkSkippedBusy;
	/** Moving players drawn without walk frames because the animation couldn't be loaded (yet). */
	long walkSkippedNoAnimation;

	/** Walk animation timing by animation id, loaded once. */
	private final Map<Integer, WalkTiming> walkTimings = new HashMap<>();

	/** Frame each player id was last drawn by the game itself, and by us, so nobody is drawn twice in a frame. */
	private final int[] nativeFrame = new int[OffsetTable.CAPACITY];
	private final int[] revealedFrame = new int[OffsetTable.CAPACITY];

	/** Scratch list for the players held back on one tile this frame. */
	private final int[] held = new int[64];

	SpreadingDrawCallbacks(Client client, OffsetTable offsets, StackRegistry stacks, StackProbe probe, RenderCallbackManager renderCallbacks, DrawCallbacks delegate)
	{
		this.client = client;
		this.offsets = offsets;
		this.stacks = stacks;
		this.probe = probe;
		this.renderCallbacks = renderCallbacks;
		this.delegate = delegate;
	}

	DrawCallbacks getDelegate()
	{
		return delegate;
	}

	// ---- the call players are drawn through --------------------------------------------

	@Override
	public void drawTemp(Projection projection, Scene scene, GameObject gameObject, Model model, int orientation, int x, int y, int z)
	{
		Renderable renderable = gameObject == null ? null : gameObject.getRenderable();
		if (!(renderable instanceof Player))
		{
			delegate.drawTemp(projection, scene, gameObject, model, orientation, x, y, z);
			return;
		}
		playerDraws++;
		if (!client.isClientThread())
		{
			offThreadDraws++;
			delegate.drawTemp(projection, scene, gameObject, model, orientation, x, y, z);
			return;
		}
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || scene != wv.getScene())
		{
			sceneMismatches++;
			delegate.drawTemp(projection, scene, gameObject, model, orientation, x, y, z);
			return;
		}

		Player drawn = (Player) renderable;
		int drawnId = drawn.getId();
		if (drawnId >= 0 && drawnId < OffsetTable.CAPACITY)
		{
			nativeFrame[drawnId] = offsets.frame();
		}
		int plane = gameObject.getPlane();
		int dx = offsets.dx(drawnId);
		int dz = offsets.dz(drawnId);
		boolean touchedSharedModel = false;
		if (dx != 0 || dz != 0)
		{
			Model drawModel = model;
			int drawOrientation = stacks.drawOrientation(StackRegistry.key(plane, x >> 7, z >> 7), orientation, dx, dz);
			if (offsets.isWalking(drawnId))
			{
				Model walk = walkModel(drawn, drawnId);
				touchedSharedModel = true;
				if (walk != null)
				{
					drawModel = walk;
					drawOrientation = offsets.walkOrientation(drawnId);
					walkDraws++;
				}
			}
			delegate.drawTemp(projection, scene, gameObject, drawModel, drawOrientation,
				x + dx, y + groundDelta(wv, plane, x, z, x + dx, z + dz), z + dz);
			nudgedDraws++;
		}
		else
		{
			delegate.drawTemp(projection, scene, gameObject, model, orientation, x, y, z);
		}

		// Only a player standing exactly in the middle of its tile hides others there.
		if (!stacks.isEmpty() && StillnessTracker.isCentred(x, z))
		{
			touchedSharedModel |= drawHiddenStackmates(projection, scene, gameObject, drawn, wv, plane, x, y, z);
		}

		if (touchedSharedModel)
		{
			// Animated models share one buffer inside the game. Building other models (or this
			// player's walking model) overwrote the one the game uses for its click test right
			// after this call returns, so rebuild it to put it back.
			try
			{
				drawn.getModel();
			}
			catch (RuntimeException e)
			{
				revealErrors++;
			}
		}
	}

	/**
	 * This player's model mid-step: their own walk animation at the frame matching how long they've
	 * been walking. Returns null (draw them as the game did) if they're busy with an action such as
	 * sitting or smithing, or the animation can't be read. Their real animation state is restored
	 * before returning; the model stays valid until the next model is built.
	 */
	private Model walkModel(Player player, int id)
	{
		if (player.getAnimation() != -1)
		{
			walkSkippedBusy++;
			return null;
		}
		int walk = player.getWalkAnimation();
		if (walk < 0)
		{
			return null;
		}
		int frame = walkTiming(walk).frameAt(offsets.walkSeconds(id));
		if (frame < 0)
		{
			walkSkippedNoAnimation++;
			return null;
		}
		int pose = player.getPoseAnimation();
		int poseFrame = player.getPoseAnimationFrame();
		try
		{
			player.setPoseAnimation(walk);
			player.setPoseAnimationFrame(frame);
			return player.getModel();
		}
		finally
		{
			player.setPoseAnimation(pose);
			player.setPoseAnimationFrame(poseFrame);
		}
	}

	private WalkTiming walkTiming(int animationId)
	{
		WalkTiming timing = walkTimings.get(animationId);
		if (timing == null || (timing.missing() && offsets.frame() - timing.loadedFrame > RETRY_FRAMES))
		{
			// A walk animation that couldn't be read is tried again a little later rather than
			// given up on for good, so a player doesn't glide for the rest of the session.
			timing = WalkTiming.load(client, animationId);
			timing.loadedFrame = offsets.frame();
			walkTimings.put(animationId, timing);
		}
		return timing;
	}

	/** How many frames to wait before trying to read a missing walk animation again (about a second). */
	private static final int RETRY_FRAMES = 50;

	/** How long each frame of a walk animation lasts, in game cycles (20 ms). */
	static final class WalkTiming
	{

		private final int[] frameLengths;
		private final int duration;
		/** Frame this was read on, for retrying a missing animation. */
		int loadedFrame;

		WalkTiming(int[] frameLengths, int duration)
		{
			this.frameLengths = frameLengths;
			this.duration = duration;
		}

		static WalkTiming load(Client client, int animationId)
		{
			try
			{
				Animation animation = client.loadAnimation(animationId);
				if (animation == null)
				{
					return new WalkTiming(null, 0);
				}
				if (animation.isMayaAnim())
				{
					return new WalkTiming(null, animation.getDuration());
				}
				int[] lengths = animation.getFrameLengths();
				return lengths == null || lengths.length == 0 ? new WalkTiming(null, 0) : new WalkTiming(lengths, 0);
			}
			catch (RuntimeException e)
			{
				return new WalkTiming(null, 0);
			}
		}

		boolean missing()
		{
			return frameLengths == null && duration <= 0;
		}

		/** Frame to show after walking this many seconds, looping; -1 if unknown. */
		int frameAt(float seconds)
		{
			int cycles = (int) (seconds / 0.02f);
			if (frameLengths == null)
			{
				return duration > 0 ? cycles % duration : -1;
			}
			int total = 0;
			for (int length : frameLengths)
			{
				total += Math.max(1, length);
			}
			int t = cycles % total;
			for (int i = 0; i < frameLengths.length; i++)
			{
				t -= Math.max(1, frameLengths[i]);
				if (t < 0)
				{
					return i;
				}
			}
			return frameLengths.length - 1;
		}
	}

	/**
	 * Draw the players the game skipped on the drawn player's tile.
	 *
	 * <p>A mate still standing exactly where the drawn player is was certainly skipped, because the
	 * game draws only one centred player per tile. A mate that has since stepped off-centre is
	 * drawn by the game itself, so it is left alone to avoid drawing anyone twice.
	 */
	private boolean drawHiddenStackmates(Projection projection, Scene scene, GameObject gameObject, Player drawn, WorldView wv, int plane, int x, int y, int z)
	{
		long tileKey = StackRegistry.key(plane, x >> 7, z >> 7);
		int[] mates = stacks.membersAt(tileKey);
		int frame = offsets.frame();
		int heldCount = probe.heldOn(tileKey, frame, held);
		if (mates.length == 0 && heldCount == 0)
		{
			return false;
		}

		// The y the game passed is ground height minus the drawn player's own animation lift.
		int ground = y + drawn.getAnimationHeightOffset();
		int cycle = client.getGameCycle();
		boolean touchedSharedModel = false;
		// As in the game, only one player is drawn in the middle of a tile: anyone left without a spot
		// (past the "players per tile" limit, or standing in the middle with you) stays hidden there.
		// Players with a spot are always drawn, and so are you.
		boolean middleDrawn = offsets.dx(drawn.getId()) == 0 && offsets.dz(drawn.getId()) == 0;
		Player local = client.getLocalPlayer();
		int localId = local == null ? -1 : local.getId();
		int total = mates.length + heldCount;
		for (int i = 0; i < total; i++)
		{
			int id = i < mates.length ? mates[i] : held[i - mates.length];
			if (id == drawn.getId() || id < 0 || id >= OffsetTable.CAPACITY
				|| nativeFrame[id] == frame || revealedFrame[id] == frame)
			{
				continue; // already drawn this frame, by the game or by us
			}
			try
			{
				Player mate = wv.players().byIndex(id);
				if (mate == null)
				{
					continue;
				}
				LocalPoint lp = mate.getLocalLocation();
				if (lp == null || lp.getX() != x || lp.getY() != z)
				{
					continue;
				}
				int mdx = offsets.dx(id);
				int mdz = offsets.dz(id);
				boolean inMiddle = mdx == 0 && mdz == 0 && !offsets.isWalking(id);
				if (inMiddle && middleDrawn && id != localId && stacks.isUnplaced(id))
				{
					continue;
				}
				if (!probe.isConfirmed(id, mate, cycle))
				{
					continue; // the game hasn't shown this player recently, e.g. hidden by the server: never draw them
				}
				if (!probe.othersAllow(renderCallbacks, mate))
				{
					continue; // hidden by another plugin, e.g. Entity Hider: respect that
				}
				touchedSharedModel = true;
				int mateOrientation = stacks.drawOrientation(tileKey, mate.getCurrentOrientation(), mdx, mdz);
				Model mateModel = null;
				if (offsets.isWalking(id))
				{
					mateModel = walkModel(mate, id);
					if (mateModel != null)
					{
						mateOrientation = offsets.walkOrientation(id);
						walkDraws++;
					}
				}
				if (mateModel == null)
				{
					mateModel = mate.getModel();
				}
				if (mateModel == null)
				{
					continue;
				}
				int mateY = ground - mate.getAnimationHeightOffset() + groundDelta(wv, plane, x, z, x + mdx, z + mdz);
				delegate.drawTemp(projection, scene, gameObject, mateModel, mateOrientation, x + mdx, mateY, z + mdz);
				revealedFrame[id] = frame;
				revealedDraws++;
				middleDrawn |= inMiddle;
			}
			catch (RuntimeException e)
			{
				revealErrors++;
			}
		}

		return touchedSharedModel;
	}

	/** Height difference between the ground at the real spot and at the drawn spot, or 0 if unknown. */
	private int groundDelta(WorldView wv, int plane, int x, int z, int nx, int nz)
	{
		if (nx == x && nz == z)
		{
			return 0;
		}
		int maxX = wv.getSizeX() * Perspective.LOCAL_TILE_SIZE;
		int maxZ = wv.getSizeY() * Perspective.LOCAL_TILE_SIZE;
		if (x < 0 || z < 0 || nx < 0 || nz < 0 || x >= maxX || nx >= maxX || z >= maxZ || nz >= maxZ)
		{
			return 0;
		}
		try
		{
			int before = Perspective.getTileHeight(client, new LocalPoint(x, z, wv), plane);
			int after = Perspective.getTileHeight(client, new LocalPoint(nx, nz, wv), plane);
			return after - before;
		}
		catch (RuntimeException e)
		{
			return 0;
		}
	}

