package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

public class CombatWatchTest
{
	@Test
	public void attackingAMonsterThatIsFightingSomeoneElseCounts()
	{
		// Multi-combat: you hit a giant that is attacking another player, so only its health bar shows.
		Assert.assertTrue(new CombatWatch().update(false, true, true, 1));
	}

	@Test
	public void beingHitCounts()
	{
		Assert.assertTrue(new CombatWatch().update(true, false, false, 1));
	}

	@Test
	public void fishingOrTalkingDoesNotCount()
	{
		// Interacting with a fishing spot or someone you talk to: no health bar on them.
		CombatWatch watch = new CombatWatch();
		Assert.assertFalse(watch.update(false, true, false, 1));
		Assert.assertFalse(watch.update(false, false, false, 2));
	}

	@Test
	public void staysInCombatForAFewTicksAfterTheFight()
	{
		CombatWatch watch = new CombatWatch();
		watch.update(false, true, true, 10);
		for (int t = 11; t <= 10 + CombatWatch.LINGER_TICKS; t++)
		{
			Assert.assertTrue("tick " + t, watch.update(false, false, false, t));
		}
		Assert.assertFalse(watch.update(false, false, false, 11 + CombatWatch.LINGER_TICKS));
	}

	@Test
	public void clearForgetsTheLastFight()
	{
		CombatWatch watch = new CombatWatch();
		watch.update(true, false, false, 5);
		watch.clear();
		Assert.assertFalse(watch.update(false, false, false, 6));
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

public class CollisionTerrainTest
{
	private static final int SIZE = 20;
	private static final int TX = 10;
	private static final int TZ = 10;
	private static final int CX = TX * 128 + 64;
	private static final int CZ = TZ * 128 + 64;

	private static int[][][] openGround()
	{
		int[][][] flags = new int[4][][];
		flags[0] = new int[SIZE][SIZE];
		return flags;
	}

	@Test
	public void nobodyIsDrawnInsideABlockedTileOrAgainstIt()
	{
		// A bank booth on the tile to the north.
		int[][][] flags = openGround();
		flags[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		CollisionTerrain terrain = new CollisionTerrain(flags);
		Assert.assertFalse("inside the booth", terrain.canStand(0, CX, CZ, CX, CZ + 128));
		Assert.assertFalse("pressed against the booth", terrain.canStand(0, CX, CZ, CX, CZ + 60));
		Assert.assertTrue(terrain.canStand(0, CX, CZ, CX, CZ + 20));
		Assert.assertTrue("open to the south", terrain.canStand(0, CX, CZ, CX, CZ - 100));
	}

	@Test
	public void wallsAreNotCrossed()
	{
		// Wall along the east edge of the tile.
		int[][][] flags = openGround();
		flags[0][TX][TZ] |= CollisionTerrain.BLOCK_EAST;
		flags[0][TX + 1][TZ] |= CollisionTerrain.BLOCK_WEST;
		CollisionTerrain terrain = new CollisionTerrain(flags);
		Assert.assertFalse("across the wall", terrain.canStand(0, CX, CZ, CX + 100, CZ));
		Assert.assertFalse("against the wall", terrain.canStand(0, CX, CZ, CX + 50, CZ));
		Assert.assertTrue(terrain.canStand(0, CX, CZ, CX - 100, CZ));
	}

	@Test
	public void noMapMeansNoLimits()
	{
		Assert.assertTrue(new CollisionTerrain(new int[4][][]).canStand(0, CX, CZ, CX + 300, CZ));
	}

	@Test
	public void facingAnAnvilOrAWallCountsButOpenFloorDoesNot()
	{
		int[][][] anvil = openGround();
		anvil[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		Assert.assertTrue(new CollisionTerrain(anvil).facesObstacle(0, TX, TZ, Math.PI));
		Assert.assertFalse("facing away from it", new CollisionTerrain(anvil).facesObstacle(0, TX, TZ, 0));

		int[][][] wall = openGround();
		wall[0][TX][TZ] |= CollisionTerrain.BLOCK_EAST;
		Assert.assertTrue(new CollisionTerrain(wall).facesObstacle(0, TX, TZ, 3 * Math.PI / 2));

		Assert.assertFalse(new CollisionTerrain(openGround()).facesObstacle(0, TX, TZ, Math.PI));
	}

	@Test
	public void aRowOfBoothsIsACounterButASingleAnvilIsNot()
	{
		// Facing north (pi) from the tile at (TX, TZ).
		int[][][] booths = openGround();
		for (int x = TX - 2; x <= TX + 2; x++)
		{
			booths[0][x][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		}
		Assert.assertTrue(new CollisionTerrain(booths).isCounter(0, TX, TZ, Math.PI));

		int[][][] anvil = openGround();
		anvil[0][TX][TZ + 1] = CollisionTerrain.BLOCK_FULL;
		Assert.assertFalse(new CollisionTerrain(anvil).isCounter(0, TX, TZ, Math.PI));

		Assert.assertFalse("open floor", new CollisionTerrain(openGround()).isCounter(0, TX, TZ, Math.PI));
		Assert.assertFalse("facing along the counter, not at it", new CollisionTerrain(booths).isCounter(0, TX, TZ, Math.PI / 2));
	}

	@Test
	public void aCounterWallCountsToo()
	{
		// A wall along the north edge of three tiles in a row.
		int[][][] flags = openGround();
		for (int x = TX - 1; x <= TX + 1; x++)
		{
			flags[0][x][TZ] |= CollisionTerrain.BLOCK_NORTH;
			flags[0][x][TZ + 1] |= CollisionTerrain.BLOCK_SOUTH;
		}
		Assert.assertTrue(new CollisionTerrain(flags).isCounter(0, TX, TZ, Math.PI));
	}

	@Test
	public void terrainStepRules()
	{
		int[][] f = new int[3][3];
		Assert.assertTrue(CollisionTerrain.canStep(f, 1, 1, 1, 0));
		f[2][1] = CollisionTerrain.BLOCK_FULL;
		Assert.assertFalse("can't step onto a blocked tile", CollisionTerrain.canStep(f, 1, 1, 1, 0));
		f[2][1] = 0;
		f[1][1] = CollisionTerrain.BLOCK_NORTH;
		Assert.assertFalse("wall on the north edge", CollisionTerrain.canStep(f, 1, 1, 0, 1));
		Assert.assertFalse("diagonal past that wall", CollisionTerrain.canStep(f, 1, 1, 1, 1));
		Assert.assertTrue(CollisionTerrain.canStep(f, 1, 1, 0, -1));
		Assert.assertFalse("off the map", CollisionTerrain.canStep(f, 2, 2, 1, 0));
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class ShapeMemoryTest
{
	private static final long TILE = 7L;

	private static List<StackSpreader.Entry> group(int... idAndOrientation)
	{
		List<StackSpreader.Entry> g = new ArrayList<>();
		for (int i = 0; i < idAndOrientation.length; i += 2)
		{
			g.add(new StackSpreader.Entry(idAndOrientation[i], TILE, false, idAndOrientation[i + 1]));
		}
		return g;
	}

	private static ShapeMemory.Shape tick(ShapeMemory memory, List<StackSpreader.Entry> group)
	{
		memory.startTick();
		return memory.decide(TILE, group, true);
	}

	@Test
	public void aPlayerTurningDoesNotChangeTheShape()
	{
		ShapeMemory memory = new ShapeMemory();
		ShapeMemory.Shape first = tick(memory, group(1, 1024, 2, 1024));
		Assert.assertTrue("both face north: a row", first.row);

		// Player 2 starts casting and spins round to face south, then east.
		ShapeMemory.Shape turned = tick(memory, group(1, 1024, 2, 0));
		Assert.assertTrue("same people: still a row", turned.row);
		Assert.assertEquals(first.angle, turned.angle, 1e-9);
		ShapeMemory.Shape turnedAgain = tick(memory, group(1, 1024, 2, 1536));
		Assert.assertEquals(first.angle, turnedAgain.angle, 1e-9);
	}

	@Test
	public void aCrowdBecomesARowOnceEveryoneTurnsToFaceTheSameThing()
	{
		// Two players walk up to a bank booth facing different ways, then both turn to face it.
		ShapeMemory memory = new ShapeMemory();
		Assert.assertFalse(tick(memory, group(1, 0, 2, 1024)).row);
		ShapeMemory.Shape turned = tick(memory, group(1, 1024, 2, 1024));
		Assert.assertTrue(turned.row);
		// One of them turns away again: still a row, so nobody moves.
		Assert.assertTrue(tick(memory, group(1, 0, 2, 1024)).row);
		Assert.assertEquals("one change, never back", 1, memory.changes);
	}

	@Test
	public void someoneArrivingLetsTheShapeBeReconsidered()
	{
		ShapeMemory memory = new ShapeMemory();
		Assert.assertFalse(tick(memory, group(1, 0, 2, 1024)).row);
		Assert.assertTrue(tick(memory, group(1, 1024, 2, 1024, 3, 1024)).row);
	}

	@Test
	public void aRowKeepsItsDirectionThroughSmallChangesWhenSomeoneArrives()
	{
		ShapeMemory memory = new ShapeMemory();
		ShapeMemory.Shape first = tick(memory, group(1, 1024, 2, 1024));
		// A newcomer facing a little off to one side: the row doesn't swing round for them.
		ShapeMemory.Shape after = tick(memory, group(1, 1024, 2, 1024, 3, 1150));
		Assert.assertTrue(after.row);
		Assert.assertEquals(first.angle, after.angle, 1e-9);
	}

	@Test
	public void someoneSteppingAwayAndBackDoesNotFlipTheTile()
	{
		ShapeMemory memory = new ShapeMemory();
		// Two players facing different ways: a crowd.
		Assert.assertFalse(tick(memory, group(1, 1024, 2, 0)).row);
		// Player 2 drops out for a moment. Player 1 alone would count as a row, but must not.
		Assert.assertFalse("a departure keeps the shape", tick(memory, group(1, 1024)).row);
		// Player 2 comes back: not a newcomer, nothing to reconsider.
		Assert.assertFalse(tick(memory, group(1, 1024, 2, 0)).row);
		Assert.assertEquals("no shape changes at all", 0, memory.changes);
	}

	@Test
	public void aRealNewcomerStillCountsAfterSomeoneLeft()
	{
		ShapeMemory memory = new ShapeMemory();
		Assert.assertFalse(tick(memory, group(1, 0, 2, 1024)).row);
		tick(memory, group(1, 1024));
		Assert.assertTrue("player 3 is new, and everyone faces north", tick(memory, group(1, 1024, 3, 1024)).row);
		Assert.assertEquals(1, memory.changes);
	}

	@Test
	public void circleArrangementNeverMakesRows()
	{
		ShapeMemory memory = new ShapeMemory();
		memory.startTick();
		Assert.assertFalse(memory.decide(TILE, group(1, 1024, 2, 1024), false).row);
	}

	@Test
	public void angleBetweenWrapsRound()
	{
		Assert.assertEquals(Math.toRadians(20), ShapeMemory.angleBetween(Math.toRadians(350), Math.toRadians(10)), 1e-9);
		Assert.assertEquals(Math.PI, ShapeMemory.angleBetween(0, Math.PI), 1e-9);
	}
}

package com.grant9008.personalspace;

import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class StatusSummaryTest
{
	/** A snapshot of the plugin happily spreading players at the GE. Tests break one thing at a time. */
	private static Snapshot working()
	{
		Snapshot s = new Snapshot();
		s.active = true;
		s.mode = PersonalSpaceConfig.Mode.SPREAD;
		s.spacing = PersonalSpaceConfig.SPACING_NORMAL;
		s.maxStack = 5;
		s.testOffset = 32;
		s.gate = Snapshot.Gate.SAFE;
		s.renderer = "GPU plugin";
		s.hooked = true;
		s.playerDrawsPerSec = 300;
		s.nudgedDrawsPerSec = 40;
		s.nearby = 80;
		s.still = 50;
		s.stackedTiles = 2;
		s.moving = 4;
		return s;
	}

	private static StatusSummary.Headline headline(Snapshot s)
	{
		return StatusSummary.headline(s);
	}

	@Test
	public void workingSaysHowManyAreSpread()
	{
		StatusSummary.Headline h = headline(working());
		Assert.assertEquals(StatusSummary.Level.OK, h.level);
		Assert.assertEquals("Spreading 4 players on 2 tiles", h.title);
	}

	@Test
	public void singularWording()
	{
		Snapshot s = working();
		s.moving = 1;
		s.stackedTiles = 1;
		Assert.assertEquals("Spreading 1 player on 1 tile", headline(s).title);
	}

	@Test
	public void pausedWinsOverEverythingElse()
	{
		Snapshot s = working();
		s.active = false;
		s.renderer = null;
		Assert.assertEquals(StatusSummary.Level.PAUSED, headline(s).level);
	}

	@Test
	public void notLoggedInIsWaitingNotAProblem()
	{
		Snapshot s = working();
		s.gate = Snapshot.Gate.NOT_LOGGED_IN;
		s.hooked = false;
		Assert.assertEquals(StatusSummary.Level.WAITING, headline(s).level);
	}

	@Test
	public void safetyGatesSayWhy()
	{
		Snapshot s = working();
		s.gate = Snapshot.Gate.WILDERNESS;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.PAUSED, h.level);
