	}

	@Test
	public void noRendererTellsYouToTurnOnGpu()
	{
		Snapshot s = working();
		s.renderer = null;
		s.hooked = false;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.PROBLEM, h.level);
		Assert.assertTrue(h.title.contains("GPU"));
	}

	@Test
	public void notHookedIsAProblem()
	{
		Snapshot s = working();
		s.hooked = false;
		Assert.assertEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void aBriefGapInPlayerDrawsIsNotAlarming()
	{
		Snapshot s = working();
		s.playerDrawsPerSec = 0;
		s.nudgedDrawsPerSec = 0;
		Assert.assertNotEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void sustainedNoPlayerDrawsIsAProblem()
	{
		Snapshot s = working();
		s.playerDrawsPerSec = 0;
		s.noPlayerDrawsSustained = true;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.PROBLEM, h.level);
		Assert.assertTrue(h.detail.contains("Copy report"));
	}

	@Test
	public void noStackedPlayersIsWaiting()
	{
		Snapshot s = working();
		s.stackedTiles = 0;
		s.moving = 0;
		s.nudgedDrawsPerSec = 0;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.WAITING, h.level);
		Assert.assertEquals("No crowds here", h.title);
	}

	@Test
	public void revealingHiddenPlayersAloneCountsAsWorking()
	{
		Snapshot s = working();
		s.nudgedDrawsPerSec = 0; // e.g. you are the drawn player and stay put
		s.revealedDrawsPerSec = 120;
		Assert.assertEquals(StatusSummary.Level.OK, headline(s).level);
	}

	@Test
	public void oddityRowCoversEveryShouldNeverHappenCounter()
	{
		Snapshot s = working();
		s.offThreadDraws = 1;
		Assert.assertTrue(hasLabel(StatusSummary.checks(s), "Oddities"));
		s = working();
		s.revealErrors = 2;
		Assert.assertTrue(hasLabel(StatusSummary.checks(s), "Oddities"));
	}

	@Test
	public void stackedButNotYetDrawnMovedIsWaitingUntilSustained()
	{
		Snapshot s = working();
		s.nudgedDrawsPerSec = 0;
		Assert.assertEquals(StatusSummary.Level.WAITING, headline(s).level);
		s.nothingMovedSustained = true;
		Assert.assertEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void testModeWorking()
	{
		Snapshot s = working();
		s.mode = PersonalSpaceConfig.Mode.TEST_SHIFT_ME;
		s.stackedTiles = 0;
		s.moving = 1;
		StatusSummary.Headline h = headline(s);
		Assert.assertEquals(StatusSummary.Level.OK, h.level);
		Assert.assertTrue(h.detail.contains("32 units"));
		Assert.assertEquals("Test mode is on", h.title);
	}

	@Test
	public void testModeWithZeroOffsetExplainsTheSlider()
	{
		Snapshot s = working();
		s.mode = PersonalSpaceConfig.Mode.TEST_SHIFT_ME;
		s.testOffset = 0;
		s.moving = 0;
		s.nudgedDrawsPerSec = 0;
		Assert.assertEquals(StatusSummary.Level.WAITING, headline(s).level);
	}

	@Test
	public void testModeSustainedNothingShiftedIsAProblem()
	{
		Snapshot s = working();
		s.mode = PersonalSpaceConfig.Mode.TEST_SHIFT_ME;
		s.moving = 1;
		s.nudgedDrawsPerSec = 0;
		s.nothingMovedSustained = true;
		Assert.assertEquals(StatusSummary.Level.PROBLEM, headline(s).level);
	}

	@Test
	public void checksHideSafetyAndDrawRateWhenLoggedOut()
	{
		Snapshot s = working();
		s.gate = Snapshot.Gate.NOT_LOGGED_IN;
		List<StatusSummary.Check> checks = StatusSummary.checks(s);
		for (StatusSummary.Check c : checks)
		{
			Assert.assertNotEquals("Safety", c.label);
			Assert.assertNotEquals("Players drawn", c.label);
		}
	}

	@Test
	public void oddityRowAppearsOnlyWhenSomethingOddHappened()
	{
		Snapshot s = working();
		Assert.assertFalse(hasLabel(StatusSummary.checks(s), "Oddities"));
		s.playersInOtherCalls = 3;
		Assert.assertTrue(hasLabel(StatusSummary.checks(s), "Oddities"));
	}

	@Test
	public void reportContainsTheNumbersNeededToDebug()
	{
		Snapshot s = working();
		String r = StatusSummary.report(s);
		Assert.assertTrue(r.startsWith("Personal Space " + PersonalSpacePlugin.VERSION));
		Assert.assertTrue(r.contains("Renderer: GPU plugin, connected yes"));
		Assert.assertTrue(r.contains("Player draws/sec: 300"));
		Assert.assertTrue(r.contains("stacked tiles: 2"));
		Assert.assertTrue(r.contains("players in other calls (should be 0): 0"));
		Assert.assertTrue(r.contains("hidden shown/sec: 0"));
		Assert.assertTrue(r.contains("pause in combat yes"));
	}

	private static boolean hasLabel(List<StatusSummary.Check> checks, String label)
	{
		for (StatusSummary.Check c : checks)
		{
			if (c.label.equals(label))
			{
				return true;
			}
		}
		return false;
	}
}

package com.grant9008.personalspace;

import org.junit.Assert;
import org.junit.Test;

public class StillnessTrackerTest
{
	private static final long TILE_A = 10L;
	private static final long TILE_B = 11L;

	@Test
	public void standingInTheMiddleOfOneTileForTwoTicksCountsAsStill()
	{
		StillnessTracker t = new StillnessTracker();
		Assert.assertFalse("one tick is not enough", t.observe(7, TILE_A, true, 1));
		Assert.assertTrue(t.observe(7, TILE_A, true, 2));
		Assert.assertTrue("and stays still", t.observe(7, TILE_A, true, 3));
	}

	@Test
	public void beingBetweenTilesIsNeverStill()
	{
		StillnessTracker t = new StillnessTracker();
		Assert.assertFalse(t.observe(7, TILE_A, false, 1));
		Assert.assertFalse(t.observe(7, TILE_A, false, 2));
	}

	@Test
	public void walkingOntoANewTileResetsStillness()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		Assert.assertTrue(t.observe(7, TILE_A, true, 2));
		Assert.assertFalse("arrived on a different tile", t.observe(7, TILE_B, true, 3));
		Assert.assertTrue("then waited a tick there", t.observe(7, TILE_B, true, 4));
	}

	@Test
	public void passingThroughTheCentreMidWalkDoesNotCount()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		Assert.assertFalse(t.observe(7, TILE_A, false, 2));
		Assert.assertFalse("stillness must restart after moving", t.observe(7, TILE_A, true, 3));
	}

	@Test
	public void aMissedTickResetsStillness()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		Assert.assertFalse("not seen on tick 2, so tick 3 starts over", t.observe(7, TILE_A, true, 3));
	}

	@Test
	public void clearForgetsEveryone()
	{
		StillnessTracker t = new StillnessTracker();
		t.observe(7, TILE_A, true, 1);
		t.clear();
		Assert.assertFalse(t.observe(7, TILE_A, true, 2));
	}

	@Test
	public void outOfRangeIdsAreIgnored()
	{
		StillnessTracker t = new StillnessTracker();
		Assert.assertFalse(t.observe(-1, TILE_A, true, 1));
		Assert.assertFalse(t.observe(OffsetTable.CAPACITY, TILE_A, true, 1));
	}

	@Test
	public void centreOfATileIsHalfATileIn()
	{
		Assert.assertTrue(StillnessTracker.isCentred(64, 64));
		Assert.assertTrue(StillnessTracker.isCentred(128 * 40 + 64, 128 * 7 + 64));
		Assert.assertFalse(StillnessTracker.isCentred(128 * 40 + 70, 128 * 7 + 64));
		Assert.assertFalse(StillnessTracker.isCentred(128 * 40, 128 * 7 + 64));
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Assert;
import org.junit.Test;

public class StackRegistryTest
{
	@Test
	public void keysAreDistinctAcrossPlaneAndBothAxes()
	{
		Set<Long> keys = new HashSet<>();
		for (int plane = 0; plane < 4; plane++)
		{
			for (int x = 0; x < 200; x += 7)
			{
				for (int y = 0; y < 200; y += 7)
				{
					Assert.assertTrue("duplicate key for " + plane + "," + x + "," + y, keys.add(StackRegistry.key(plane, x, y)));
				}
			}
		}
		Assert.assertNotEquals(StackRegistry.key(0, 1, 2), StackRegistry.key(0, 2, 1));
	}

	@Test
	public void emptyUntilRebuiltAndNeverReturnsNull()
	{
		StackRegistry r = new StackRegistry();
		Assert.assertTrue(r.isEmpty());
		Assert.assertEquals(0, r.membersAt(StackRegistry.key(0, 10, 10)).length);
	}

	@Test
	public void rebuildGroupsPlacementsByTile()
	{
		long a = StackRegistry.key(0, 40, 50);
		long b = StackRegistry.key(0, 41, 50);
		List<StackSpreader.Placement> placements = new ArrayList<>();
		placements.add(new StackSpreader.Placement(3, a, 32, 0));
		placements.add(new StackSpreader.Placement(9, a, -32, 0));
		placements.add(new StackSpreader.Placement(5, b, 32, 0));

		StackRegistry r = new StackRegistry();
		r.rebuild(placements);
		Assert.assertFalse(r.isEmpty());
		Assert.assertArrayEquals(new int[]{3, 9}, r.membersAt(a));
		Assert.assertArrayEquals(new int[]{5}, r.membersAt(b));
		Assert.assertEquals(0, r.membersAt(StackRegistry.key(1, 40, 50)).length);
	}

	@Test
	public void rebuildReplacesTheOldTable()
	{
		long a = StackRegistry.key(0, 40, 50);
		long b = StackRegistry.key(0, 60, 60);
		StackRegistry r = new StackRegistry();
		List<StackSpreader.Placement> first = new ArrayList<>();
		first.add(new StackSpreader.Placement(3, a, 32, 0));
		r.rebuild(first);
		List<StackSpreader.Placement> second = new ArrayList<>();
		second.add(new StackSpreader.Placement(4, b, 32, 0));
		r.rebuild(second);
		Assert.assertEquals("old tile gone", 0, r.membersAt(a).length);
		Assert.assertArrayEquals(new int[]{4}, r.membersAt(b));

		r.rebuild(new ArrayList<>());
		Assert.assertTrue(r.isEmpty());
	}

	@Test
	public void clearEmptiesTheTable()
	{
		long a = StackRegistry.key(0, 40, 50);
		List<StackSpreader.Placement> placements = new ArrayList<>();
		placements.add(new StackSpreader.Placement(3, a, 32, 0));
		StackRegistry r = new StackRegistry();
		r.rebuild(placements);
		r.clear();
		Assert.assertTrue(r.isEmpty());
		Assert.assertEquals(0, r.membersAt(a).length);
	}

	@Test
	public void playersRoundAFireFaceItAndCurvedRowsTurnIn()
	{
		long fireTile = StackRegistry.key(0, 2, 2);
		long rowTile = StackRegistry.key(0, 3, 3);
		StackRegistry r = new StackRegistry();
		r.rebuild(new ArrayList<>(), java.util.Collections.singleton(rowTile), java.util.Collections.emptySet(),
			java.util.Collections.singletonMap(fireTile, new int[]{128, 0}));
		Assert.assertEquals("west of the fire, facing east", 1536, r.drawOrientation(fireTile, 0, -80, 0));
		Assert.assertEquals(StackSpreader.faceSameSpot(1024, 60, 0), r.drawOrientation(rowTile, 1024, 60, 0));
		Assert.assertEquals("anywhere else, their own facing", 700, r.drawOrientation(StackRegistry.key(0, 9, 9), 700, 60, 0));
	}

	@Test
	public void posedPairsFaceOrAngleTowardsEachOther()
	{
		long facing = StackRegistry.key(0, 4, 4);
		long angled = StackRegistry.key(0, 5, 5);
		java.util.Map<Long, PersonalSpaceConfig.Pose> poses = new java.util.HashMap<>();
		poses.put(facing, PersonalSpaceConfig.Pose.FACING);
		poses.put(angled, PersonalSpaceConfig.Pose.ANGLED);
		StackRegistry r = new StackRegistry();
		r.rebuild(new ArrayList<>(), java.util.Collections.emptySet(), java.util.Collections.emptySet(), java.util.Collections.emptyMap(), poses);
		// Drawn east of the middle: facing each other means facing west.
		Assert.assertEquals(512, r.drawOrientation(facing, 0, 80, 0));
		Assert.assertEquals(1536, r.drawOrientation(facing, 0, -80, 0));
		// Both really facing south (the camera): angled turns each halfway in.
		Assert.assertEquals(256, r.drawOrientation(angled, 0, 80, 0));
		Assert.assertEquals(1792, r.drawOrientation(angled, 0, -80, 0));
		Assert.assertEquals("someone in the middle keeps their facing", 300, r.drawOrientation(facing, 300, 0, 0));
	}

	@Test
	public void playersWithoutASpotAreRemembered()
	{
		long tile = StackRegistry.key(0, 1, 1);
		List<StackSpreader.Placement> members = new ArrayList<>();
		members.add(new StackSpreader.Placement(1, tile, 40, 0));
		members.add(new StackSpreader.Placement(2, tile, 0, 0));
		StackRegistry r = new StackRegistry();
		r.rebuild(members, java.util.Collections.emptySet(), java.util.Collections.singleton(2));
		Assert.assertTrue(r.isUnplaced(2));
		Assert.assertFalse(r.isUnplaced(1));
		r.clear();
		Assert.assertFalse(r.isUnplaced(2));
	}

	@Test
	public void plannedPlayersCarryTheirTileIntoTheRegistry()
	{
		long tile = StackRegistry.key(0, 12, 34);
		List<StackSpreader.Entry> entries = new ArrayList<>();
		entries.add(new StackSpreader.Entry(1, tile, true, 1024));
		entries.add(new StackSpreader.Entry(2, tile, false, 0));
		entries.add(new StackSpreader.Entry(3, tile, false, 512));

		CrowdPlanner.Surroundings open = new CrowdPlanner.Surroundings()
		{
			@Override
			public boolean canStand(long t, int dx, int dz)
			{
				return true;
			}

			@Override
			public boolean facesObstacle(long t, double angle)
			{
				return false;
			}

			@Override
			public boolean isCounter(long t, double angle)
			{
				return false;
			}

			@Override
			public boolean facesFire(long t, double angle)
			{
				return false;
			}

			@Override
			public List<int[]> firesNear(long t)
			{
				return new ArrayList<>();
			}
		};
		CrowdPlanner.Plan plan = new CrowdPlanner().plan(entries, id -> true, 32, 5, true, false, 1, open);
		StackRegistry r = new StackRegistry();
		r.rebuild(plan.placements);
		Assert.assertArrayEquals("local player stays put, the other two are placed on the tile", new int[]{2, 3}, r.membersAt(tile));
	}
}

package com.grant9008.personalspace;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Assert;
import org.junit.Test;

public class SlotBookTest
{
	private static final long TILE = 42L;

	private static Map<Integer, Integer> step(SlotBook book, int tick, Integer... ids)
	{
		Map<Long, List<Integer>> present = new HashMap<>();
		if (ids.length > 0)
		{
			present.put(TILE, Arrays.asList(ids));
		}
		Map<Long, Map<Integer, Integer>> out = book.update(present, tile -> 5, tick);
		return out.getOrDefault(TILE, Collections.emptyMap());
	}

	@Test
	public void newcomersTakeTheNextSpotAndNobodyElseMoves()
	{
		SlotBook book = new SlotBook();
		Map<Integer, Integer> a = step(book, 1, 10, 20);
		Assert.assertEquals(0, (int) a.get(10));
		Assert.assertEquals(1, (int) a.get(20));

		Map<Integer, Integer> b = step(book, 2, 10, 20, 5); // a lower id arrives
		Assert.assertEquals("existing players keep their spots", 0, (int) b.get(10));
		Assert.assertEquals(1, (int) b.get(20));
		Assert.assertEquals("newcomer goes to the next spot", 2, (int) b.get(5));
	}

	@Test
	public void aSpotIsHeldForSomeoneWhoStepsAwayBriefly()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2, 3);
		Map<Integer, Integer> gone = step(book, 2, 1, 3); // 2 steps away
		Assert.assertEquals("3 stays put while 2's spot is held", 2, (int) gone.get(3));
		Map<Integer, Integer> back = step(book, 4, 1, 2, 3);
		Assert.assertEquals("2 gets its spot back", 1, (int) back.get(2));
		Assert.assertEquals(2, (int) back.get(3));
	}

	@Test
	public void aNewcomerDoesNotTakeAHeldSpot()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2, 3);
		step(book, 2, 1, 3);
		Map<Integer, Integer> m = step(book, 3, 1, 3, 9);
		Assert.assertEquals("9 goes past the held spot", 3, (int) m.get(9));
	}

	@Test
	public void whenAHoldRunsOutOnlyTheBackPlayerMovesForward()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2, 3, 4);
		step(book, 2, 1, 3, 4); // 2 leaves for good
		Map<Integer, Integer> m = step(book, 2 + SlotBook.HOLD_TICKS + 1, 1, 3, 4);
		Assert.assertEquals("front stays", 0, (int) m.get(1));
		Assert.assertEquals("middle stays", 2, (int) m.get(3));
		Assert.assertEquals("the back player fills the gap", 1, (int) m.get(4));
	}

	@Test
	public void aFullTileLeavesExtrasWithoutASpot()
	{
		SlotBook book = new SlotBook();
		Map<Integer, Integer> m = step(book, 1, 1, 2, 3, 4, 5, 6, 7);
		Assert.assertEquals(5, m.size());
		Assert.assertFalse(m.containsKey(6));
		Assert.assertFalse(m.containsKey(7));
	}

	@Test
	public void holdsKeepATileRememberedAfterEveryoneLeaves()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2);
		step(book, 2);
		Map<Integer, Integer> back = step(book, 5, 2, 1);
		Assert.assertEquals("both get their own spots back", 0, (int) back.get(1));
		Assert.assertEquals(1, (int) back.get(2));
	}

	@Test
	public void youGetTheFrontSpotAndOnlyOnePersonMakesRoom()
	{
		SlotBook book = new SlotBook();
		book.localId = 99;
		Map<Integer, Integer> before = step(book, 1, 10, 20, 30);
		Map<Integer, Integer> arrived = step(book, 2, 10, 20, 30, 99);
		Assert.assertEquals("at first you take the next free spot and nobody moves", 3, (int) arrived.get(99));
		Map<Integer, Integer> after = arrived;
		for (int t = 3; t <= 2 + SlotBook.LOCAL_SWAP_DELAY; t++)
		{
			after = step(book, t, 10, 20, 30, 99);
		}
		Assert.assertEquals("once you've stayed a moment you get the best spot", 0, (int) after.get(99));
		int moved = 0;
		for (Map.Entry<Integer, Integer> e : before.entrySet())
		{
			moved += e.getValue().equals(after.get(e.getKey())) ? 0 : 1;
		}
		Assert.assertEquals("only whoever had it moves", 1, moved);
		Assert.assertEquals("and then everyone stays put", after, step(book, 20, 10, 20, 30, 99));
	}

	@Test
	public void stoppingForAMomentOnYourWayPastPushesNobodyAround()
	{
		SlotBook book = new SlotBook();
		book.localId = 99;
		Map<Integer, Integer> before = step(book, 1, 10, 20, 30);
		for (int t = 2; t <= 40; t++)
		{
			boolean stopped = t % 12 == 0 || t % 12 == 1;
			Map<Integer, Integer> now = stopped ? step(book, t, 10, 20, 30, 99) : step(book, t, 10, 20, 30);
			for (Map.Entry<Integer, Integer> e : before.entrySet())
			{
				Assert.assertEquals("tick " + t + ": player " + e.getKey() + " was moved", e.getValue(), now.get(e.getKey()));
			}
		}
	}

	@Test
	public void youDontSwapWhileABetterSpotIsHeldForSomeone()
	{
		// The front player steps away; you arrive; their hold runs out. Nobody else moves at all:
		// you step into the freed front spot.
		SlotBook book = new SlotBook();
		book.localId = 99;
		Map<Integer, Integer> before = step(book, 1, 10, 20, 30, 40);
		for (int t = 2; t <= 30; t++)
		{
			Map<Integer, Integer> now = t < 5 ? step(book, t, 10, 20, 30, 40) : t < 8 ? step(book, t, 20, 30, 40) : step(book, t, 20, 30, 40, 99);
			for (int id : new int[]{20, 30, 40})
			{
				Assert.assertEquals("tick " + t + ": player " + id + " was moved", before.get(id), now.get(id));
			}
		}
		Assert.assertEquals(0, (int) step(book, 31, 20, 30, 40, 99).get(99));
	}

	@Test
	public void youWalkOnceToTheFrontEvenWhenAMiddleSpotIsFree()
	{
		SlotBook book = new SlotBook();
		book.localId = 99;
		step(book, 1, 10, 20, 30, 40, 99);
		// 20 and 30 leave: their spots are held for a while, then free.
		Map<Integer, Integer> before = null;
		for (int t = 2; t <= 1 + SlotBook.HOLD_TICKS + 2; t++)
		{
			before = step(book, t, 10, 40, 99);
		}
		Assert.assertEquals("you end up at the front", 0, (int) before.get(99));
		for (int t = 1; t <= 4; t++)
		{
			Assert.assertEquals("and then nobody moves", before, step(book, 20 + t, 10, 40, 99));
		}
	}

	@Test
	public void walkingInBesideSomeoneSettlesInOneStep()
	{
		// The other player has the lower id, so without first pick they would take the front spot and
		// you would swap with them a few ticks later: the pair shuffling about once for no reason.
		SlotBook book = new SlotBook();
		book.localId = 99;
		// A tile with one person on it isn't laid out, so the pair's spots are both handed out the
		// tick you arrive: the other player has the lower id and would otherwise take the front one.
		Map<Integer, Integer> pair = step(book, 1, 7, 99);
		Assert.assertEquals("you take the front spot as you arrive", 0, (int) pair.get(99));
		for (int t = 2; t <= 2 + SlotBook.LOCAL_SWAP_DELAY + 2; t++)
		{
			Assert.assertEquals("and then nobody shuffles", pair, step(book, t, 7, 99));
		}
	}

	@Test
	public void clearForgetsEverything()
	{
		SlotBook book = new SlotBook();
		step(book, 1, 1, 2);
		book.clear();
		Map<Integer, Integer> m = step(book, 2, 2);
		Assert.assertEquals(0, (int) m.get(2));
	}
}

package com.grant9008.personalspace;

import java.util.ArrayList;
import java.util.List;
import org.junit.Assert;
import org.junit.Test;

public class StackSpreaderTest
{
	private static final long TILE_A = 1L;
	private static final long TILE_B = 2L;

	@Test
	public void stackedTilesCountsOnlyTilesWithTwoOrMore()
	{
		List<StackSpreader.Entry> in = new ArrayList<>();
		Assert.assertEquals(0, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(1, TILE_A, false));
		in.add(new StackSpreader.Entry(2, TILE_B, false));
		Assert.assertEquals(0, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(3, TILE_A, false));
		Assert.assertEquals(1, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(4, TILE_A, false));
		Assert.assertEquals("a third player on the same tile is still one stacked tile", 1, StackSpreader.stackedTiles(in));
		in.add(new StackSpreader.Entry(5, TILE_B, false));
		Assert.assertEquals(2, StackSpreader.stackedTiles(in));
	}

	@Test
	public void aWideRowCurvesRoundTheThingInsteadOfRunningPastIt()
	{
		// Players facing north at an anvil, widest spacing: the front row stays a tile from the anvil
		// spot, doesn't go past its sides, and everyone turned to face the same spot faces the anvil.
		double focusX = 0;
		double focusZ = StackSpreader.LOOK_AHEAD;
		for (int[] o : StackSpreader.spots(true, false, Math.PI, false, PersonalSpaceConfig.MAX_SPACING, 6, null))
		{
			Assert.assertEquals("everyone is the same distance from the anvil", StackSpreader.LOOK_AHEAD,
				Math.hypot(o[0] - focusX, o[1] - focusZ), 2);
			Assert.assertTrue("went past the anvil: z " + o[1], o[1] < focusZ - 30);

			int facing = StackSpreader.faceSameSpot(1024, o[0], o[1]);
			double lookX = -Math.sin(StackSpreader.toRadians(facing));
			double lookZ = -Math.cos(StackSpreader.toRadians(facing));
			double toAnvilX = focusX - o[0];
			double toAnvilZ = focusZ - o[1];
			double cos = (lookX * toAnvilX + lookZ * toAnvilZ) / Math.hypot(toAnvilX, toAnvilZ);
			Assert.assertTrue("isn't facing the anvil from " + o[0] + "," + o[1], cos > 0.99);
		}
	}

	@Test
	public void curvedRowsBehindKeepTheFrontRowsAngles()
	{
		// Facing north: row two's whole steps sit exactly between row one's half steps.
		List<int[]> spots = StackSpreader.spots(true, false, Math.PI, false, 72, StackSpreader.CURVED_ROW_WIDTH + 2, null);
		double front = Math.atan2(spots.get(0)[0], StackSpreader.LOOK_AHEAD - spots.get(0)[1]);
		double back = Math.atan2(spots.get(StackSpreader.CURVED_ROW_WIDTH + 1)[0], StackSpreader.LOOK_AHEAD - spots.get(StackSpreader.CURVED_ROW_WIDTH + 1)[1]);
		Assert.assertEquals("row two's first step out is twice row one's half step", 2 * front, back, 0.02);
	}

	@Test
	public void aGroupFacingTheSameWayHasASharedFacing()
	{
		List<StackSpreader.Entry> group = new ArrayList<>();
		group.add(new StackSpreader.Entry(1, TILE_A, false, 1024));
		group.add(new StackSpreader.Entry(2, TILE_A, false, 1000));
		Double facing = StackSpreader.sharedFacing(group, StackSpreader.SAME_FACING);
		Assert.assertNotNull(facing);
		Assert.assertEquals(Math.PI, Math.abs(facing), 0.1);

		group.add(new StackSpreader.Entry(3, TILE_A, false, 0));
		Assert.assertNull("one facing the other way: no shared facing", StackSpreader.sharedFacing(group, StackSpreader.SAME_FACING));

		List<StackSpreader.Entry> unknown = new ArrayList<>();
		unknown.add(new StackSpreader.Entry(1, TILE_A, false));
		unknown.add(new StackSpreader.Entry(2, TILE_A, false));
		Assert.assertNull(StackSpreader.sharedFacing(unknown, StackSpreader.SAME_FACING));
	}

	@Test
	public void endsOfARowTurnInTowardsWhatEveryoneIsFacing()
	{
		// Facing north (1024) at an anvil. Pushed east, you turn to the north-west to still face it.
		int east = StackSpreader.faceSameSpot(1024, 88, 0);
		Assert.assertTrue("turned towards the west: " + east, east > 512 && east < 1024);
		// Pushed west, you turn to the north-east.
		int west = StackSpreader.faceSameSpot(1024, -88, 0);
		Assert.assertTrue("turned towards the east: " + west, west > 1024 && west < 1536);
		// The further out, the more you turn.
		Assert.assertTrue(StackSpreader.faceSameSpot(1024, 120, 0) < StackSpreader.faceSameSpot(1024, 40, 0));
		// Not moved sideways: keep facing straight ahead.
		Assert.assertEquals(1024, StackSpreader.faceSameSpot(1024, 0, 0));
		Assert.assertEquals(1024, StackSpreader.faceSameSpot(1024, 0, -30));
	}

	@Test
	public void rowTilesAreRememberedForDrawing()
	{
		StackRegistry r = new StackRegistry();
		java.util.Set<Long> rows = new java.util.HashSet<>();
		rows.add(TILE_A);
		r.rebuild(new ArrayList<>(), rows);
		Assert.assertTrue(r.isCurvedRow(TILE_A));
		Assert.assertFalse(r.isCurvedRow(TILE_B));
		r.clear();
		Assert.assertFalse(r.isCurvedRow(TILE_A));
	}

	@Test
	public void twoPlayersInACrowdStandEitherSideOfTheMiddle()
	{
		List<int[]> spots = StackSpreader.spots(false, false, 0, false, 60, 5, null);
		Assert.assertEquals(5, spots.size());
		Assert.assertEquals("first spot east", 0, spots.get(0)[1]);
		Assert.assertTrue(spots.get(0)[0] > 0);
		Assert.assertEquals("second spot straight across", -spots.get(0)[0], spots.get(1)[0]);
		Assert.assertEquals(0, spots.get(1)[1]);
	}

	@Test
	public void theSpotPatternDoesNotDependOnHowManyPlayersThereAre()
	{
		for (boolean straight : new boolean[]{false, true})
		{
			for (boolean middleTaken : new boolean[]{false, true})
			{
				List<int[]> small = StackSpreader.spots(true, straight, Math.PI, middleTaken, 80, 3, null);
				List<int[]> big = StackSpreader.spots(true, straight, Math.PI, middleTaken, 80, 10, null);
				for (int i = 0; i < small.size(); i++)
				{
					Assert.assertArrayEquals("spot " + i + " must not move when the tile gets bigger", small.get(i), big.get(i));
				}
			}
		}
	}

	@Test
	public void theMiddleIsLeftForWhoeverStaysPut()
	{
		for (boolean row : new boolean[]{false, true})
		{
			for (boolean straight : new boolean[]{false, true})
			{
				List<int[]> spots = StackSpreader.spots(row, straight, Math.PI, true, 80, 10, null);
				Assert.assertEquals(10, spots.size());
				for (int[] s : spots)
				{
					Assert.assertFalse("row=" + row + ": nobody may be put in the middle", s[0] == 0 && s[1] == 0);
				}
			}
		}
	}

	@Test
	public void twoPlayersInARowShareTheSpaceEvenly()
	{
		// Facing north, at an anvil (curved row) and at a counter (straight row).
		for (boolean straight : new boolean[]{false, true})
		{
			List<int[]> spots = StackSpreader.spots(true, straight, Math.PI, false, 42, 2, null);
			Assert.assertEquals(2, spots.size());
			Assert.assertEquals("either side of the middle", -spots.get(0)[0], spots.get(1)[0]);
			Assert.assertEquals(spots.get(0)[1], spots.get(1)[1]);
			Assert.assertEquals("one spacing apart", 42.0, spots.get(0)[0] - spots.get(1)[0], 2.0);
		}
	}

	@Test
	public void aFourthPlayerAtACounterStillJoinsTheFrontRowWhenOneSideIsBlocked()
	{
		// Facing north at a counter with a rope barrier just east of the tile.
		List<int[]> spots = StackSpreader.spots(true, true, Math.PI, false, 42, 10, (dx, dz) -> dx <= 38);
		for (int i = 0; i < 4; i++)
		{
			Assert.assertEquals("spot " + i + " is in the front row", 0, spots.get(i)[1]);
			Assert.assertTrue(spots.get(i)[0] <= 38);
		}
		Assert.assertEquals("the first two still share the middle", -spots.get(0)[0], spots.get(1)[0]);
	}

	@Test
	public void aCurvedRowWrapsRoundTheThingBeforeAnyoneStandsBehind()
	{
		// Facing north: what everyone faces is 128 north of the tile centre.
		List<int[]> spots = StackSpreader.spots(true, false, Math.PI, false, 60, StackSpreader.CURVED_ROW_WIDTH + 1, null);
		for (int i = 0; i < StackSpreader.CURVED_ROW_WIDTH; i++)
		{
			Assert.assertEquals("spot " + i + " is in the front ring", 128, Math.hypot(spots.get(i)[0], 128 - spots.get(i)[1]), 1.5);
		}
		Assert.assertTrue("the next one is in the row behind",
			Math.hypot(spots.get(StackSpreader.CURVED_ROW_WIDTH)[0], 128 - spots.get(StackSpreader.CURVED_ROW_WIDTH)[1]) > 150);
	}

	@Test
	public void aRowBehindStandsInTheGaps()
	{
		List<int[]> spots = StackSpreader.spots(true, true, Math.PI, false, 42, StackSpreader.ROW_WIDTH + 1, null);
		Assert.assertEquals("the second row starts straight behind the middle", 0, spots.get(StackSpreader.ROW_WIDTH)[0]);
		Assert.assertTrue(spots.get(StackSpreader.ROW_WIDTH)[1] < 0);
	}

	@Test
	public void aCurvedRowNeverWrapsPastTheWrapLimit()
	{
		for (int spacing : new int[]{PersonalSpaceConfig.MIN_SPACING, 72, 160, PersonalSpaceConfig.MAX_SPACING})
		{
			for (boolean middleTaken : new boolean[]{false, true})
			{
				for (int[] s : StackSpreader.spots(true, false, Math.PI, middleTaken, spacing, 17, null))
				{
					double round = Math.atan2(Math.abs(s[0]), 128 - s[1]);
					Assert.assertTrue("spacing " + spacing + ": " + Math.toDegrees(round) + " degrees round",
						round <= StackSpreader.WRAP_ARC + 0.02);
				}
			}
		}
	}

	@Test
	public void blockedSpotsAreSkippedAndTheNextOneIsUsed()
	{
		// Anything to the north (into a booth) is off limits.
		List<int[]> spots = StackSpreader.spots(false, false, 0, false, 80, 6, (dx, dz) -> dz <= 20);
		Assert.assertEquals(6, spots.size());
		for (int[] s : spots)
		{
			Assert.assertTrue("spot in the booth: " + s[1], s[1] <= 20);
		}
	}

	@Test
	public void wideSpacingDoesNotFlingRowsFarBack()
	{
		for (boolean straight : new boolean[]{false, true})
		{
			for (int[] s : StackSpreader.spots(true, straight, Math.PI, false, PersonalSpaceConfig.MAX_SPACING, 17, null))
			{
				Assert.assertTrue("at most two row-depths back: " + s[1], s[1] >= -2 * StackSpreader.ROW_DEPTH - 2);
			}
		}
	}

	@Test
	public void backRowsStandBehindTheFrontRow()
	{
		// Facing north: the front row is nearer the thing, row two is a spacing further back.
		int back = StackSpreader.CURVED_ROW_WIDTH;
		List<int[]> spots = StackSpreader.spots(true, false, Math.PI, false, 80, back + 1, null);
		Assert.assertTrue("back row is further south: " + spots.get(0)[1] + " vs " + spots.get(back)[1], spots.get(back)[1] < spots.get(0)[1] - 40);
	}

	@Test
	public void firesAreRecognisedByName()
	{
		Assert.assertTrue(StackSpreader.isFireName("Fire"));
		Assert.assertTrue(StackSpreader.isFireName("Forester's Campfire"));
		Assert.assertTrue(StackSpreader.isFireName("Fire pit"));
		Assert.assertFalse(StackSpreader.isFireName("Fireplace"));
		Assert.assertFalse(StackSpreader.isFireName("Anvil"));
		Assert.assertFalse(StackSpreader.isFireName(null));
	}
}

package com.grant9008.personalspace;

